// who the famous people were, in a few lines: the first is their life and death, the rest are curious facts (keys are the Bulgarian names)
export const BIO_BG: Record<string, string[]> = {
  "Имхотеп": ["Египетски мъдрец и съветник на фараона Джосер. Построява първата пирамида в света, стъпаловидната пирамида в Сакара. Освен строител е бил и лечител, а годината и начинът на смъртта му не са известни.", "Той е първият архитект в историята, чието име знаем.", "Около 2000 години след смъртта му египтяните започват да му се молят като на бог на лечението."],
  "Хамурапи": ["Цар на Вавилон, който обединява почти цяла Месопотамия. Записва 282 закона върху висока черна каменна плоча, за да знае всеки какво е справедливо. Умира стар и болен след около 42 години на трона.", "Плочата със законите му е намерена през 1901 г. и днес стои в Лувъра в Париж.", "Оттам идва правилото „око за око, зъб за зъб“."],
  "Моисей": ["Според Библията извежда евреите от робството в Египет и ги води 40 години през пустинята. На планината Синай получава десетте Божи заповеди. Умира на 120 години на планината Нево, откъдето вижда обетованата земя, но не стъпва в нея.", "Като бебе майка му го слага в кошница по река Нил, а го намира дъщерята на фараона.", "Статуята му от Микеланджело има рога заради грешка в превода на думата за „лъчи“."],
  "Нефертити": ["Египетска царица, съпруга на фараона Ехнатон. Двамата заменят многото стари богове с един – слънчевия диск Атон. Не се знае как и кога умира, а гробът ѝ още не е открит.", "Името ѝ означава „Красавицата дойде“.", "Прочутият ѝ цветен бюст е намерен от германски археолози през 1912 г. и днес е в Берлин."],
  "Тутанкамон": ["Става фараон на около 9 години и управлява Египет едва десетина години. Умира млад, на около 18–19, вероятно от болест след счупен крак. Става световноизвестен, когато Хауърд Картър открива почти недокоснатата му гробница през 1922 г.", "Златната му маска тежи около 10 килограма.", "В гробницата има над 130 бастуна – той е куцал и е ходел с тях."],
  "Рамзес II": ["Най-могъщият фараон на Египет, управлява 66 години. Строи огромни храмове, сред тях Абу Симбел, и води битката при Кадеш срещу хетите. Умира на около 90 години, надживял много от децата си.", "Мирният му договор с хетите е най-старият известен в света; копие от него виси в ООН.", "Има над 100 деца."],
  "Цар Давид": ["Според Библията е овчарче, което побеждава великана Голиат с един камък от прашка. По-късно става цар на Израел и прави Ерусалим своя столица. Умира на 70 години и оставя трона на сина си Соломон.", "Традицията му приписва много от псалмите.", "Мраморният „Давид“ на Микеланджело е висок над 5 метра."],
  "Цар Соломон": ["Син на Давид и цар на Израел, прочут с мъдростта и богатството си. Построява първия храм в Ерусалим. Умира след около 40 години на трона, а след него царството се разделя на две.", "В прочутия „Соломонов съд“ две жени спорят за едно бебе; той предлага да го разсекат и така познава истинската майка – тя се отказва, за да го спаси.", "Посещава го царицата на Сава, за да изпита мъдростта му."],
  "Солон": ["Атински законодател, един от „Седемте мъдреци“. Опрощава дълговете на бедните и забранява да се продават хора в робство заради дълг. Така поставя основите на атинската демокрация и умира на около 80 години.", "След като дава законите, заминава на път за 10 години, за да не го карат да ги променя.", "На богатия цар Крез казва: „Не наричай никого щастлив, преди да е умрял.“"],
  "Сафо": ["Поетеса от остров Лесбос, която пее стиховете си на лира. Пише за любовта, приятелството и красотата. Как умира, не се знае; легендата, че скача от скала заради любов, вероятно е измислица.", "Платон я нарича „десетата муза“.", "От деветте ѝ книги е оцеляло едно цяло стихотворение, останалото са парчета от папируси."],
  "Езоп": ["Разказвач на басни, който според преданието е бил роб на остров Самос и после е освободен. Животните в баснитe му – лисицата, костенурката, заекът – учат хората на ум. Според легендата е убит в Делфи, хвърлен от скала.", "Изразът „кисело грозде“ идва от баснята му за лисицата, която не стига гроздето.", "Баснята „Заекът и костенурката“ е негова."],
  "Питагор": ["Роден на остров Самос, основава училище в Кротон, Южна Италия. Учениците му вярват, че светът е направен от числа. Умира на около 75 години; според легендата е убит, защото отказва да избяга през поле с боб.", "Теоремата му a² + b² = c² е била известна на вавилонците още по-рано.", "Пръв открива, че хубавите музикални тонове са прости съотношения на числа."],
  "Буда": ["Принц Сидхарта Гаутама, роден в Лумбини, днешен Непал. На 29 години напуска двореца, след като вижда старост, болест и смърт. Под дървото Бодхи достига просветление и 45 години учи хората как да се освободят от страданието. Умира на 80 години в Кушинагар.", "„Буда“ означава „Пробуденият“.", "Дебелият усмихнат „Буда“ от статуетките всъщност е друг човек – китайският монах Будай."],
  "Конфуций": ["Учител от царство Лу в Китай. Учи на уважение към родителите, учене цял живот и честно управление. Умира на 72 години, а учениците му записват мислите му в книгата „Беседи и съждения“.", "Негово е правилото: „Не прави на другите това, което не искаш да правят на теб.“", "Родословното му дърво е проследено над 80 поколения – най-дългото в света."],
  "Есхил": ["Атинянин, наречен „бащата на трагедията“. Бие се срещу персите при Маратон, а после пише около 90 пиеси, от които са оцелели 7. Умира на 69 години в Сицилия.", "Легендата разказва, че орел пуска костенурка върху плешивата му глава, като я взема за камък.", "На гроба му пише само, че се е бил при Маратон – за пиесите си не споменава."],
  "Софокъл": ["Атински драматург, автор на „Цар Едип“ и „Антигона“. Пише 123 пиеси, 7 са оцелели, и печели първа награда около 24 пъти. Умира на 91 години, творил до самия край.", "Пръв въвежда трети актьор на сцената.", "Когато синовете му искат да го обявят за невменяем, той прочита в съда от новата си пиеса и печели делото."],
  "Перикъл": ["Водач на Атина в златния ѝ век. Укрепва демокрацията и строи Партенона на Акропола. Умира на 66 години от чумата, която покосява Атина по време на войната със Спарта.", "Винаги го изобразяват с шлем – говори се, за да скрие необичайно дългата си глава.", "Речта му за загиналите във войната и днес се смята за една от най-великите речи за демокрацията."],
  "Херодот": ["Роден в Халикарнас, днешен Бодрум в Турция. Пътува до Египет, Вавилон и Черно море и записва всичко видяно в „Истории“ – разказ за войните между гърци и перси. Умира на около 59 години, вероятно в Южна Италия.", "Цицерон го нарича „бащата на историята“.", "Някои го наричат и „бащата на лъжите“ – пише например за мравки в Индия, големи колкото лисици, които копаят злато."],
  "Сократ": ["Атинянин, син на каменоделец, който не написва нито ред. Разхожда се по площада и задава въпроси, докато хората не открият сами истината. Осъден е на смърт, защото „покварявал младежта“, и на 71 години изпива чаша с отрова от бучиниш.", "Негова е мисълта „Знам, че нищо не знам“.", "Ходел бос и бил прочут с некрасивото си лице, но младите атиняни го обожавали."],
  "Хипократ": ["Лекар от остров Кос, наречен „бащата на медицината“. Пръв учи, че болестите имат естествени причини, а не са наказание от боговете. Умира в дълбока старост в Лариса; легендата казва, че е живял над 90 години.", "И днес лекарите полагат „Хипократова клетва“.", "Описва болести толкова точно, че някои още носят неговото име."],
  "Демокрит": ["Роден в Абдера, Тракия, недалеч от днешната българска граница. Пръв казва, че всичко е съставено от мънички неделими частици – атоми. Умира на около 90 години, весел до края.", "„Атом“ на гръцки означава „неразрязваем“.", "Наричат го „смеещия се философ“, защото се шегувал с човешката глупост."],
  "Платон": ["Атинянин, ученик на Сократ. Основава Академията – училище, което съществува около 900 години. Пише диалози, в които Сократ разговаря с хората, и умира на около 80 години в Атина.", "„Платон“ е прякор, който означава „широкия“ – вероятно заради раменете му на борец.", "Пръв разказва за изчезналия остров Атлантида."],
  "Аристотел": ["Роден в Стагира, ученик на Платон и учител на Александър Македонски. Пише за почти всичко: логика, физика, животни, поезия и държава. Умира в Халкида на 62 години, след като напуска Атина.", "Пръв подрежда животните в групи и описва над 500 вида.", "Учи учениците си, докато се разхожда – затова школата му се казва „перипатетическа“, тоест „разхождаща се“."],
  "Александър Македонски": ["Роден в Пела, Македония, ученик на Аристотел. Става цар на 20 години и за 11 години завладява Персийската империя чак до Индия, без да загуби битка. Умира на 32 години във Вавилон от треска.", "Основава около 20 града с името Александрия; най-прочутата е в Египет.", "Като момче укротява коня Буцефал, като забелязва, че той се плаши от собствената си сянка, и го обръща към слънцето."],
  "Евклид": ["Математик от Александрия, за чийто живот почти нищо не се знае. Книгата му „Елементи“ събира цялата геометрия на времето си в 13 тома. Тя е учебник по математика повече от 2000 години.", "На цар Птолемей, който искал по-лесен път към геометрията, отговаря: „Няма царски път към геометрията.“", "След Библията „Елементи“ е може би най-много издаваната книга в историята."],
  "Ашока": ["Император от династията Маурия, който управлява почти цяла Индия. След кървавата война с Калинга се разкайва, приема будизма и проповядва ненасилие. Издълбава законите си на каменни колони из цялата империя и умира на около 72 години.", "Лъвовете от неговата колона в Сарнатх са държавният герб на Индия.", "Колелото от колоните му е в средата на индийското знаме."],
  "Архимед": ["Учен от Сиракуза в Сицилия, един от най-великите математици на всички времена. Открива закона за плаването на телата и изобретява машини за защита на града. Убит е на 75 години от римски войник, когато римляните превземат Сиракуза.", "Според легендата открива закона си във ваната и тича по улицата, викайки „Еврика!“ – „Открих!“.", "Последните му думи към войника били: „Не ми разваляй кръговете!“"],
  "Цин Шъхуан": ["Става цар на 13 години и на 38 обединява Китай като негов пръв император. Въвежда една писменост, едни пари и едни мерки за цялата страна и започва Великата китайска стена. Умира на 49 години, вероятно отровен от живачни хапчета, които трябвало да го направят безсмъртен.", "Погребан е с Теракотената армия – около 8000 глинени войници, всеки с различно лице.", "Армията е открита случайно през 1974 г. от селяни, които копаят кладенец."],
  "Ханибал": ["Пълководец от Картаген, който като момче се заклева във вечна вражда с Рим. Преминава Алпите с армия и бойни слонове и разбива римляните при Кана. Накрая е победен и на около 64 години изпива отрова, за да не попадне в ръцете на римляните.", "Римляните дълго плашат децата си с думите „Ханибал пред портите!“.", "От около 37 слона, с които тръгва през Алпите, оцеляват съвсем малко."],
  "Спартак": ["Тракиец, вероятно от земите на днешна България, пленен и продаден в Рим като гладиатор. През 73 г. пр.н.е. бяга от гладиаторската школа и вдига най-голямото въстание на роби срещу Рим, с десетки хиляди последователи. Загива в битка на около 40 години.", "Паметникът му стои в Сандански, където според преданието е роден.", "Робите му побеждават няколко римски армии, преди Рим да изпрати срещу тях Марк Крас."],
  "Цицерон": ["Най-великият оратор на Рим, консул и защитник на републиката. След убийството на Цезар напада Марк Антоний в пламенни речи. На 63 години е убит по заповед на Антоний.", "Запазени са стотици негови писма – от тях знаем как живеят римляните всеки ден.", "Той измисля латинските думи „qualitas“ (качество) и „moralis“ (нравствен), които днес живеят в много езици."],
  "Юлий Цезар": ["Римски пълководец, който завладява Галия и с армията си пресича река Рубикон, за да вземе властта в Рим. Става пожизнен диктатор и въвежда календара с високосна година. На мартенските иди на 44 г. пр.н.е. е намушкан 23 пъти от сенатори, на 55 години.", "Месец юли носи неговото име.", "От името му идват думите „кайзер“ и „цар“."],
  "Вергилий": ["Поет, роден край Мантуа в Северна Италия. Пише „Енеида“ – поемата за троянеца Еней, от чийто род произлизат римляните. Умира на 50 години от треска и иска поемата да бъде изгорена като недовършена, но император Август отказва.", "Данте го избира за свой водач през Ада в „Божествена комедия“.", "Над 10 години пише „Енеида“ и пак я смята за незавършена."],
  "Клеопатра": ["Последната владетелка на Древен Египет, от гръцкия род на Птолемеите. Съюзява се първо с Юлий Цезар, после с Марк Антоний срещу Рим. След поражението им сама слага край на живота си на 39 години, по легендата с ухапване от аспид.", "Тя е първата от рода си, която научава египетски, а говори около девет езика.", "Живее по-близо до днешния ден, отколкото до строежа на Хеопсовата пирамида."],
  "Октавиан Август": ["Племенник и осиновен син на Юлий Цезар. Побеждава Антоний и Клеопатра и става първият римски император. Управлява 41 години в мир, наречен „Pax Romana“, и умира на 75 години.", "Месец август носи неговото име.", "Казва: „Заварих Рим от тухли, а го оставям от мрамор.“"],
  "Исус Христос": ["Роден във Витлеем, израства в Назарет. Около 30-годишен започва да проповядва любов към ближния и прошка и събира около себе си ученици. На около 33 години е разпнат в Ерусалим, а християните вярват, че възкръсва на третия ден.", "Летоброенето ни започва от раждането му, но монахът, който го изчислява, сбърква с няколко години – вероятно е роден около 4 г. пр.н.е.", "Говорил е арамейски."],
  "Апостол Павел": ["Савел от Тарс отначало преследва християните, но по пътя за Дамаск има видение и става най-ревностният им проповедник. Изминава хиляди километри из Мала Азия и Гърция и основава църкви. Обезглавен е в Рим по времето на Нерон.", "Посланията му са почти половината от книгите в Новия завет.", "По занаят е майстор на палатки."],
  "Нерон": ["Става римски император на 16 години. Обича да пее и да се състезава, а след големия пожар в Рим през 64 г. обвинява християните. Когато сенатът го обявява за враг, на 30 години се самоубива.", "Последните му думи са: „Какъв артист умира в мен!“", "Историята, че свирел, докато Рим гори, е мит – тогава е бил на 50 км, в Анциум."],
  "Птолемей": ["Астроном и географ от Александрия. Описва света със Земята в центъра, а Слънцето и планетите около нея – представа, в която хората вярват около 1400 години. Умира на около 70 години.", "48 от съзвездията, които е описал, се използват и днес.", "Картите му дават на Земята по-малък размер от истинския – затова Колумб смята, че Индия е близо."],
  "Марк Аврелий": ["Римски император и философ стоик. Голяма част от управлението си прекарва във войни по Дунав и там пише за себе си „Размисли“. Умира на 58 години по време на поход, вероятно от чума.", "Бронзовата му статуя на кон оцелява, защото дълго са я мислели за статуя на Константин Велики.", "Пише „Размисли“ на гръцки, а не на латински."],
  "Константин Велики": ["Роден в Наисус, днешен Ниш. Първият римски император, приел християнството: с Миланския едикт от 313 г. дава свобода на християните. Основава Константинопол и умира на 65 години, кръстен на смъртния си одър.", "Обича Сердика (днешна София) и според преданието казва: „Сердика е моят Рим.“", "Преди решаваща битка вижда в небето кръст и думите „С този знак ще победиш“."],
  "Свети Августин": ["Роден в Тагаст, днешен Алжир. Младостта си прекарва бурно, но на 32 години става християнин, а после епископ на Хипон. Умира на 75 години, докато вандалите обсаждат града.", "„Изповед“ е може би първата автобиография в историята.", "В младостта си се моли: „Господи, дай ми чистота – но не още.“"],
  "Хипатия": ["Математичка, астрономка и философка от Александрия, дъщеря на математика Теон. Преподава открито пред мъже и жени и е уважавана в целия град. На около 55 години е убита от разярена тълпа.", "Тя е първата жена математик, за чийто живот знаем достатъчно.", "Филмът „Агора“ от 2009 г. разказва за нея."],
  "Атила": ["Цар на хуните, наречен „Бич Божи“. Опустошава Балканите, включително Сердика, а после Галия и Италия. Умира на 47 години в първата си брачна нощ от силно кървене от носа.", "Папа Лъв I го убеждава да не напада Рим.", "Погребан е в три ковчега – златен, сребърен и железен, а гробът му никога не е намерен."],
  "Юстиниан I": ["Византийски император, роден в село край днешно Скопие. Строи църквата „Света София“ в Константинопол и събира римските закони в един сборник. Управлява 38 години и умира на 83.", "Законите му са в основата на правото в половин Европа и до днес.", "Съпругата му Теодора, бивша актриса, е била най-близката му съветничка."],
  "Мохамед": ["Роден в Мека, остава сирак като малък и става търговец. На 40 години според исляма получава първото откровение в пещера край Мека. Основава исляма и умира на 62 години в Медина.", "Ислямският календар започва от преселването му от Мека в Медина през 622 г.", "Според преданието не е можел да чете и пише."],
  "Хан Аспарух": ["Син на хан Кубрат, който води своите българи от степите до Дунав. През 680 г. разбива византийската армия при Онгъла, а през 681 г. Византия признава новата държава – Дунавска България. Загива около 700 г. в битка с хазарите.", "България е една от малкото европейски държави, запазили името си повече от 1300 години.", "Според някои учени гробът му е край село Вознесенка в Украйна."],
  "Карл Велики": ["Крал на франките, който обединява голяма част от Западна Европа. На Коледа през 800 г. папата го коронясва за император в Рим. Подкрепя училищата и книгите и умира на 71 години в Аахен.", "Думата „крал“ в славянските езици идва от неговото име.", "Самият той почти не може да пише – държи плочки под възглавницата си, за да се упражнява."],
  "Хан Крум": ["Български хан, наречен Страшни. Превзема Сердика през 809 г., а през 811 г. разбива византийския император Никифор във Върбишкия проход. Умира внезапно на 59 години, докато се готви да обсади Константинопол.", "От черепа на Никифор прави чаша, обкована в сребро.", "Първият български владетел със записани закони: наказва кражбата, лъжата и пиянството."],
  "Ал-Хорезми": ["Персийски учен в „Дома на мъдростта“ в Багдад. Пише книга за решаването на уравнения и разпространява индийските цифри с нулата. Умира на около 70 години.", "Думата „алгебра“ идва от заглавието на книгата му („ал-джабр“).", "От името му идва думата „алгоритъм“."],
  "Свети Методий": ["По-големият брат на Константин-Кирил, роден в Солун. Преди да стане монах, управлява славянска област на Византия. Двамата заминават за Великоморавия, а след смъртта на Кирил той става архиепископ и умира там на около 70 години през 885 г.", "Германските епископи го държат две години и половина в затвор, защото служи на славянски.", "Според преданието превежда почти цялата Библия за шест месеца."],
  "Свети Кирил": ["Роден в Солун като Константин, наричан Философ заради учеността си. Около 855–863 г. създава глаголицата, първата славянска азбука, и с брат си Методий превежда богослужебните книги. Умира на 42 години в Рим като монах с името Кирил.", "Кирилицата носи неговото име, но е създадена по-късно от учениците му в България.", "Говори много езици и спори за вярата с арабите и хазарите."],
  "Цар Борис I": ["Покръства България през 864 г. и приема името Михаил. Посреща учениците на Кирил и Методий – Климент и Наум – и с тях България става център на славянската книжовност. Оттегля се в манастир и умира там на 72 години; почитан е като светец.", "Излиза от манастира, за да свали сина си Владимир, който иска да върне езичеството, и поставя на трона Симеон.", "През 893 г. славянският език става официален в църквата и държавата."],
  "Алфред Велики": ["Крал на Уесекс в Англия, който спира нашествието на викингите. Строи укрепени градове и кара важните книги да се превеждат на английски. Умира на 50 години и е единственият английски крал, наречен Велики.", "Според легендата, докато се крие от викингите в колиба, оставя питките на домакинята да изгорят и тя му се скарва, без да знае кой е.", "Създава първия английски флот."],
  "Цар Симеон Велики": ["Син на Борис I, учил в Константинопол, затова го наричат „полугрък“. При него в Преслав настъпва Златният век на българската книжнина. През 917 г. разбива византийците при Ахелой, приема титлата цар и умира на 63 години.", "При него България стига до три морета: Черно, Бяло и Адриатическо.", "Според легенда византийците отрязват главата на една статуя, вярвайки, че тя е свързана с живота му – и той умира същия ден."],
  "Свети Иван Рилски": ["Отшелник, който живее в пещера и в хралупата на дърво в Рила. Около него се събират ученици и така се създава Рилският манастир. Умира на около 70 години и е покровител на българския народ.", "Цар Петър идва да се срещне с него, но светецът отказва – двамата само се поклонят един на друг отдалеч.", "Мощите му и днес са в Рилския манастир."],
  "Авицена": ["Персийски лекар и философ, който на 18 години вече знае всички науки на времето си. „Канон на медицината“ се учи в европейските университети около 600 години. Пише около 450 труда и умира на 57 години от болест.", "На 17 години излекува емира и получава достъп до царската библиотека.", "Пръв описва, че някои болести се разнасят чрез водата и почвата."],
  "Омар Хайям": ["Персийски математик, астроном и поет. Съставя календар, по-точен от днешния. Прочут е с четиристишията си – рубаи – за виното, любовта и краткостта на живота. Умира на 83 години в Нишапур.", "Решава уравнения от трета степен с помощта на геометрия.", "На негово име са кръстени кратер на Луната и астероид."],
  "Хилдегард фон Бинген": ["Германска игуменка, която от дете има видения. Пише за лечебни растения, медицина и природата и съчинява музика. Основава манастир край Бинген на Рейн и умира на 81 години.", "Една от първите композиторки, чиято музика знаем по име.", "Измисля свой таен език с около 1000 думи."],
  "Саладин": ["Кюрдски султан на Египет и Сирия. През 1187 г. превзема Ерусалим от кръстоносците, но пощадява жителите му. Уважаван е дори от враговете си и умира на 55 години в Дамаск от треска.", "Раздава толкова, че след смъртта му няма пари дори за погребението.", "Когато Ричард Лъвското сърце остава без кон в битка, Саладин му праща два."],
  "Ричард Лъвското сърце": ["Крал на Англия, който води Третия кръстоносен поход. На връщане е пленен в Австрия и освободен срещу огромен откуп. Умира на 41 години от стрела от арбалет при обсада във Франция.", "От десетте години на управлението си прекарва в Англия едва около шест месеца и почти не говори английски.", "Държан е в плен в замъка Дюрнщайн на Дунав."],
  "Чингис хан": ["Роден като Темуджин, израства в бедност след убийството на баща си. Обединява монголските племена и през 1206 г. става Велик хан. Създава империята, която скоро става най-голямата сухоземна империя в историята, и умира на 65 години; гробът му е неизвестен.", "Създава пощенска служба с конници и станции през цялата империя.", "Смята се, че милиони мъже днес са негови потомци."],
  "Франциск от Асизи": ["Син на богат търговец на платове от Асизи, който се отказва от всичко и живее в бедност. Основава ордена на францисканците и проповядва любов към всяко творение. Умира на 44 години.", "Проповядва на птиците и според легендата укротява вълка от Губио.", "През 1223 г. прави първата жива сцена на Рождество – с истински вол и магаре."],
  "Руми": ["Персийски поет, роден в Балх, днешен Афганистан. Семейството му бяга от монголите и се установява в Коня, Турция. Приятелството му с дервиша Шамс от Тебриз го прави поет на божествената любов. Умира на 66 години.", "Последователите му основават ордена на въртящите се дервиши.", "Днес е един от най-продаваните поети в САЩ."],
  "Тома Аквински": ["Италиански монах доминиканец, който съчетава учението на Аристотел с християнството. Пише огромната „Сума на теологията“. Умира на 49 години по пътя за събор в Лион.", "Семейството му го затваря за година в замък, за да не стане монах – не успява.", "Съучениците му го наричат „Немия вол“, защото е едър и мълчалив."],
  "Марко Поло": ["Венецианец, който на 17 години тръгва с баща си и чичо си към Китай. Служи 17 години на Кублай хан и пътува из цяла Азия. Разказва пътешествията си в генуезки затвор и умира на 69 години във Венеция.", "На смъртния си одър казва: „Не съм разказал и половината от това, което видях.“", "Разказите му за хартиените пари и черните камъни, които горят (въглищата), изумяват Европа."],
  "Данте Алигиери": ["Поет от Флоренция, автор на „Божествена комедия“ – пътуване през Ада, Чистилището и Рая. Пише я не на латински, а на говоримия тоскански език и така създава италианския книжовен език. Изгонен е завинаги от Флоренция и умира на 56 години в Равена от малария.", "Ако се върне във Флоренция, е осъден да бъде изгорен.", "В Рая го води Беатриче – момичето, което обича от деветгодишен."],
  "Йоханес Гутенберг": ["Златар от Майнц, който около 1450 г. изобретява печатната машина с подвижни метални букви. Отпечатва около 180 Библии, от които са оцелели 49. Фалира, губи работилницата си заради съдружника си и умира на 68 години.", "Книгите стават достъпни и знанието тръгва по света по-бързо от всякога.", "На старини архиепископът му дава пенсия – дрехи, жито и вино всяка година."],
  "Жана д’Арк": ["Селско момиче от Домреми, което чува гласове на светци. На 17 години води френската армия, освобождава обсадения Орлеан и довежда Карл VII до коронясването му. Пленена е и на 19 години е изгорена на клада в Руан.", "Не може да чете и подписва с кръстче.", "25 години след смъртта ѝ е обявена за невинна, а през 1920 г. – за светица."],
  "Христофор Колумб": ["Мореплавател от Генуа, който иска да стигне до Азия, плавайки на запад. През 1492 г. с три кораба стига до Бахамските острови. Прави четири пътувания и умира на 54 години, убеден, че е бил в Азия.", "Америка е кръстена не на него, а на Америго Веспучи.", "Останките му са местени толкова пъти, че и Севиля, и Санто Доминго твърдят, че са при тях."],
  "Леонардо да Винчи": ["Роден във Винчи край Флоренция, художник на „Мона Лиза“ и „Тайната вечеря“. В тетрадките си рисува летящи машини, танкове и човешкото тяло отвътре. Умира на 67 години във Франция, при крал Франсоа I.", "Левичар е и пише огледално – отдясно наляво.", "„Мона Лиза“ носи със себе си до края на живота си."],
  "Албрехт Дюрер": ["Художник и гравьор от Нюрнберг, най-великият германски майстор на своето време. Прочут е с автопортретите си, „Молещите се ръце“ и „Младият заек“. Умира на 56 години в родния си град.", "Пръв художник, който подписва творбите си със знак – „AD“ – като марка.", "Гравира носорог, без никога да е виждал такъв, само по описание в писмо."],
  "Николай Коперник": ["Роден в Торун, Полша. Доказва, че Земята и планетите обикалят около Слънцето, а не обратното. Книгата му излиза в годината на смъртта му, на 70 години; според легендата вижда първия ѝ екземпляр на смъртния си одър.", "Освен астроном е и лекар, и пише за парите.", "Гробът му е открит през 2005 г. и разпознат по ДНК от косъм, намерен в негова книга."],
  "Микеланджело": ["Скулптор, художник и архитект, роден в Капрезе, Тоскана. На 26 години започва „Давид“, а после изрисува тавана на Сикстинската капела. Проектира купола на „Свети Петър“ и умира на 88 години в Рим.", "Рисува тавана прав на скелето около четири години, с глава назад.", "След смъртта му тялото му е изнесено тайно от Рим, за да бъде погребано във Флоренция."],
  "Мартин Лутер": ["Монах и професор във Витенберг, роден в Айслебен. През 1517 г. обявява 95 тезиса срещу продаването на опрощения и така започва Реформацията. Превежда Библията на немски и умира на 62 години в същия град, в който е роден.", "Става монах след обет, даден по време на страшна буря, в която мълния пада до него.", "Преводът му оформя съвременния немски език."],
  "Рафаел": ["Художник от Урбино, един от тримата велики майстори на Ренесанса. Рисува „Атинската школа“ във Ватикана и „Сикстинската мадона“. Умира на 37 години, точно на рождения си ден.", "Двете ангелчета в долния край на „Сикстинската мадона“ са сред най-копираните картини в света.", "Погребан е в Пантеона в Рим."],
  "Хенри VIII": ["Крал на Англия, прочут с шестте си съпруги – от тях две развежда и две екзекутира. Скъсва с папата и създава Английската църква. Умира на 55 години, болен и много пълен.", "Доспехите му показват как талията му расте с годините.", "Папата му дава титлата „Защитник на вярата“ за книга срещу Лутер – и до днес съкращението ѝ стои на британските монети."],
  "Сюлейман Великолепни": ["Османски султан, който управлява 46 години, когато империята е на върха си. Обсажда Виена през 1529 г. и въвежда толкова закони, че турците го наричат Кануни – Законодателя. Умира на 71 години по време на обсада в Унгария.", "Смъртта му е пазена в тайна седмици наред, за да не се разпадне армията.", "Жени се за Хюрем – бивша робиня, която става една от най-влиятелните жени в империята."],
  "Елизабет I": ["Дъщеря на Хенри VIII и Ан Болейн, която баща ѝ екзекутира. Никога не се омъжва и казва, че е омъжена за Англия. При нея Англия побеждава Испанската армада и процъфтява театърът на Шекспир. Умира на 69 години.", "Щатът Вирджиния в САЩ е кръстен на нея – „кралицата девица“.", "Говори няколко езика и превежда книги от латински и гръцки."],
  "Мигел де Сервантес": ["Испански писател, който като войник губи владеенето на лявата си ръка в битката при Лепанто. Пиратите го пленяват и той прекарва пет години като роб в Алжир. На стари години пише „Дон Кихот“ – първия модерен роман – и умира на 68 години в Мадрид.", "Умира почти по едно и също време с Шекспир – затова 23 април е Световният ден на книгата.", "Четири пъти се опитва да избяга от робството."],
  "Уилям Шекспир": ["Роден в Стратфорд на Ейвън, актьор и драматург в Лондон. Пише около 39 пиеси, сред тях „Хамлет“ и „Ромео и Жулиета“, и 154 сонета. Умира на 52 години, вероятно на рождения си ден.", "Измисля над 1700 думи, които и днес са в английския език.", "В завещанието си оставя на съпругата си „второто най-хубаво легло“."],
  "Галилео Галилей": ["Учен от Пиза, който подобрява телескопа и открива спътниците на Юпитер и планините на Луната. Подкрепя Коперник и през 1633 г. е съден от Инквизицията и затворен под домашен арест до края на живота си. Ослепява и умира на 77 години.", "Легендата казва, че след присъдата прошепва: „И все пак се върти!“", "Църквата официално признава грешката си едва през 1992 г."],
  "Йоханес Кеплер": ["Германски астроном, роден във Вайл дер Щат. Като помощник на Тихо Брахе открива трите закона, по които планетите се движат по елипси около Слънцето. Умира на 58 години в Регенсбург.", "Години наред защитава майка си, обвинена във вещерство, и успява да я освободи.", "Пише един от първите научнофантастични разкази – за пътешествие до Луната."],
  "Рене Декарт": ["Френски философ и математик, който живее дълго в Нидерландия. Негова е мисълта „Мисля, следователно съществувам“, а координатната система се нарича на негово име – декартова. Заминава за Стокхолм да учи кралица Кристина и умира там на 53 години от пневмония.", "Обича да лежи в леглото до късно, но кралицата го кара да преподава в 5 сутринта.", "Според легендата идеята за координатите му хрумва, докато гледа муха на тавана."],
  "Рембранд": ["Холандски художник от Лайден, майстор на светлината и сянката. Рисува „Нощната стража“ и десетки автопортрети през целия си живот. Фалира и умира беден на 63 години в Амстердам.", "„Нощната стража“ всъщност е дневна сцена – потъмнява от стария лак.", "Автопортретите му показват как остарява година след година."],
  "Блез Паскал": ["Френски математик и философ. На 19 години построява сметачна машина, за да помогне на баща си, който събира данъци. Създава с Ферма теорията на вероятностите и умира на 39 години след дълго боледуване.", "Единицата за налягане „паскал“ и един език за програмиране носят неговото име.", "Пуска една от първите линии за обществен транспорт в Париж – файтони по точно разписание."],
  "Антони ван Левенхук": ["Търговец на платове от Делфт, който сам шлифова лещи и прави стотици микроскопи. Пръв вижда бактерии, червени кръвни телца и други „малки животинки“ във водата. Умира на 90 години.", "Никога не учи в университет и не знае латински – пише откритията си на холандски.", "Пази в тайна как прави лещите си."],
  "Луи XIV": ["Френски крал, наречен Краля Слънце. Става крал на 4 години и управлява 72 години – най-дълго от всички владетели в историята на Европа. Строи двореца Версай и умира на 76 години от гангрена.", "Името „Слънце“ идва от балет, в който като младеж танцува ролята на слънцето.", "Надживява сина и внука си, затова го наследява правнукът му."],
  "Исак Нютон": ["Английски учен, който открива закона за всеобщото привличане и трите закона на движението. Разлага светлината на цветове с призма и изобретява математически анализ. Умира на 84 години и е погребан в Уестминстърското абатство.", "Историята с ябълката е вярна поне наполовина – самият той я разказва на стари години, но ябълката не пада на главата му.", "Дълги години управлява монетния двор на Англия и лично гони фалшификатори."],
  "Петър Велики": ["Руски цар, висок над два метра, който иска да направи Русия европейска. Пътува инкогнито из Европа и работи като дърводелец в холандски корабостроителници. Основава Санкт Петербург и умира на 52 години.", "Въвежда данък върху брадите – който иска да е с брада, трябва да плаща.", "Изучава над десет занаята, включително вадене на зъби."],
  "Антонио Вивалди": ["Венециански композитор и свещеник, когото наричат „Червения свещеник“ заради рижата му коса. Преподава музика в сиропиталище за момичета и пише „Четирите годишни времена“ и около 500 концерта. Умира беден във Виена на 63 години.", "Музиката му е забравена за около 200 години и е преоткрита едва през XX век.", "Момичетата от сиропиталището му стават прочут оркестър, който идват да слушат от цяла Европа."],
  "Йохан Себастиан Бах": ["Германски композитор и органист от Айзенах, кантор в църквата „Свети Тома“ в Лайпциг. Пише над 1000 творби и има 20 деца. Умира на 65 години след неуспешна операция на очите.", "Като младеж изминава пеша около 400 км, за да чуе прочутия органист Букстехуде.", "Музиката му лети в космоса на златната плоча на сондите „Вояджър“."],
  "Георг Фридрих Хендел": ["Композитор, роден в Хале, Германия, който прекарва по-голямата част от живота си в Лондон. Пише ораторията „Месия“ и „Музика на водата“, свирена на баржа по Темза за краля. Ослепява и умира на 74 години; погребан е в Уестминстърското абатство.", "Публиката става на крака при хора „Алелуя“ – по традиция, защото така направил кралят.", "Става британски поданик и в Англия го смятат за свой композитор."],
  "Волтер": ["Френски писател и философ, истинско име Франсоа-Мари Аруе. Остро осмива несправедливостта и се бори за търпимост и свобода на словото, заради което е хвърлен в Бастилията и прогонван. Пише „Кандид“ и умира на 83 години в Париж.", "Забогатява, като с един математик открива грешка в държавна лотария и купува всички билети.", "Според разказите пие по десетки чаши кафе на ден."],
  "Бенджамин Франклин": ["Роден в Бостън като 15-о от 17 деца, печатар, учен и държавник. Доказва с хвърчило, че мълнията е електричество, и изобретява гръмоотвода и бифокалните очила. Сред бащите на САЩ е, подписва Декларацията за независимост и умира на 84 години във Филаделфия.", "Лицето му е на банкнотата от 100 долара.", "Никога не патентова изобретенията си – иска да са полезни на всички."],
  "Карл Линей": ["Шведски учен, който подрежда растенията и животните и дава на всеки вид две латински имена – например Homo sapiens. Описва хиляди видове и учи студенти, които пътуват по целия свят. Умира на 70 години в Упсала.", "Измисля „цветен часовник“ – цветя, които се разтварят в различен час на деня.", "Дадено му е благородническо звание и става Карл фон Линé."],
  "Фридрих Велики": ["Крал на Прусия, който свири на флейта, пише музика и е приятел с Волтер. Води Седемгодишната война и превръща Прусия в голяма сила. Умира на 74 години в двореца Сансуси край Потсдам.", "Кара селяните да садят картофи с хитрост – пази нивите си с войници, за да изглеждат ценни.", "Иска да бъде погребан при кучетата си – желанието му е изпълнено чак през 1991 г. Днес хората слагат картофи на гроба му."],
  "Мария Терезия": ["Единствената жена, управлявала Хабсбургските земи. Въвежда задължителното училище през 1774 г. и реформира държавата. Има 16 деца, сред тях френската кралица Мария Антоанета, и умира на 63 години във Виена.", "Талерът с нейния лик се сече и след смъртта ѝ и се използва като пари в Африка и Арабия чак до XX век.", "Пише хиляди писма на децата си с майчини съвети."],
  "Паисий Хилендарски": ["Монах в Хилендарския манастир на Света гора, роден в Банско. През 1762 г. завършва „История славянобългарска“, за да покаже на българите, че имат славно минало, и да ги подкани да не се срамуват от езика си. Умира на 51 години по време на пътуване из българските земи.", "„О, неразумний юроде, поради что се срамиш да се наречеш болгарин?“ – най-прочутият ред от книгата му.", "Първият препис на книгата прави Софроний Врачански през 1765 г. – така тя тръгва от ръка на ръка."],
  "Имануел Кант": ["Германски философ от Кьонигсберг, който почти никога не напуска родния си град. Пише „Критика на чистия разум“ и учи, че постъпвай така, както би искал всички да постъпват. Умира на 79 години.", "Толкова е точен, че съседите сверяват часовниците си по разходката му.", "Пропуска разходката си само веднъж – когато чете „Емил“ на Русо."],
  "Екатерина Велика": ["Германска принцеса, родена в Щетин, която се омъжва за бъдещия руски цар Петър III. Сваля го от трона и управлява Русия 34 години, като разширява империята до Черно море. Умира на 67 години.", "Сама се ваксинира срещу едра шарка, за да покаже на поданиците си, че е безопасно.", "Колекцията ѝ от картини е началото на музея Ермитаж."],
  "Джордж Вашингтон": ["Земевладелец от Вирджиния, който командва армията във войната за независимост на САЩ. Става първият президент на страната и отказва трети мандат. Умира на 67 години от инфекция на гърлото.", "Изкуствените му зъби не са дървени, а от слонова кост, метал и човешки зъби.", "Столицата на САЩ носи неговото име."],
  "Джеймс Уат": ["Шотландски майстор на инструменти, който подобрява парната машина, като ѝ добавя отделен кондензатор. Машината му прави индустриалната революция възможна. Умира на 83 години.", "Единицата за мощност „ват“ носи неговото име.", "Той измисля „конската сила“, за да обясни на хората колко силна е машината му."],
  "Жозеф-Мишел Монголфие": ["Френски производител на хартия, който заедно с брат си Етиен изобретява балона с горещ въздух. През 1783 г. балонът им издига първите живи същества в небето, а скоро и първите хора. Умира на 69 години.", "Първите пътници са овца, патица и петел – и тримата се приземяват живи.", "Идеята му хрумва, като гледа как прането над огъня се издува нагоре."],
  "Едуард Дженър": ["Английски селски лекар, който забелязва, че млекарките, прекарали кравешка шарка, не се разболяват от едра шарка. През 1796 г. ваксинира едно момче и така създава първата ваксина. Умира на 73 години.", "Думата „ваксина“ идва от латинското vacca – крава.", "През 1980 г. едрата шарка е напълно изчезнала от света благодарение на ваксината му."],
  "Йохан Волфганг фон Гьоте": ["Германски поет от Франкфурт, автор на „Фауст“ и „Страданията на младия Вертер“. Години наред е министър във Ваймар, а се занимава и с наука – пише за цветовете и растенията. Умира на 82 години във Ваймар.", "Последните му думи са: „Повече светлина!“", "След „Вертер“ младите мъже в Европа започват да се обличат като героя му – в син фрак и жълта жилетка."],
  "Волфганг Амадеус Моцарт": ["Чудото дете от Залцбург, което композира от 5-годишно и обикаля Европа с баща си. Пише над 600 творби, сред тях „Вълшебната флейта“ и недовършения „Реквием“. Умира на 35 години във Виена.", "На 14 години записва по памет цяла забранена църковна песен, след като я чува само веднъж.", "Обича билярда и има скорец, който може да изсвири началото на един от концертите му."],
  "Фридрих Шилер": ["Германски поет и драматург от Марбах, автор на „Разбойници“ и „Вилхелм Тел“. Близък приятел на Гьоте във Ваймар. Умира на 45 години от туберкулоза.", "Неговата „Ода на радостта“ е в Деветата симфония на Бетовен, а мелодията днес е химнът на Европейския съюз.", "Като млад бяга от херцога, който му забранява да пише пиеси."],
  "Робърт Фултън": ["Американец, който отначало е художник. През 1807 г. пуска по река Хъдсън първия успешен параход – „Клермонт“. Умира на 49 години след простуда през тежка зима.", "Преди парахода строи подводница за Наполеон, наречена „Наутилус“.", "Хората наричат парахода му „глупостта на Фултън“ – докато не тръгва."],
  "Наполеон Бонапарт": ["Роден на остров Корсика, става генерал и после император на французите. Завладява голяма част от Европа и оставя Наполеоновия кодекс – закони, които се ползват и днес. След поражението при Ватерло е заточен на остров Света Елена и умира там на 51 години.", "Не е бил нисък – около 1,69 м, колкото обикновен човек тогава. Митът идва от британските карикатури.", "Походът му в Русия през 1812 г. започва с около 600 000 войници, а се връщат малцина."],
  "Александър фон Хумболт": ["Германски учен и пътешественик от Берлин. Пет години изследва Южна Америка и се изкачва на вулкана Чимборасо по-високо от всеки човек преди него. Пише „Космос“ – описание на цялата природа – и умира на 89 години.", "На негово име са кръстени повече растения, животни и места, отколкото на всеки друг човек.", "Чарлз Дарвин тръгва на пътешествие, вдъхновен от книгите му."],
  "Лудвиг ван Бетовен": ["Композитор от Бон, който живее във Виена. Започва да оглушава около 30-годишен, но пише най-великите си творби, включително Деветата симфония, когато вече почти не чува. Умира на 56 години, а на погребението му идват около 20 000 души.", "Брои по 60 кафени зърна за всяка чаша кафе.", "Мелодията на „Ода на радостта“ от Деветата му симфония е химнът на Европейския съюз."],
  "Джейн Остин": ["Английска писателка, дъщеря на селски свещеник. Пише „Гордост и предразсъдъци“ и „Разум и чувства“ – остроумни романи за любовта и брака. Умира на 41 години в Уинчестър.", "Книгите ѝ излизат без името ѝ – само „от една дама“.", "Лицето ѝ е на британската банкнота от 10 лири."],
  "Карл Фридрих Гаус": ["Германски математик от Брауншвайг, наречен „княза на математиците“. Работи и в астрономията и магнетизма и заедно с Вебер прави един от първите електрически телеграфи. Умира на 77 години в Гьотинген.", "Като ученик събира числата от 1 до 100 за секунди: 50 двойки по 101.", "Кривата на Гаус и лицето му бяха на старата германска банкнота от 10 марки."],
  "Джордж Стивънсън": ["Английски миньорски син, който научава да чете едва на 18 години. Строи първите истински железници и със сина си Робърт – локомотива „Ракета“. Наричат го „бащата на железниците“ и умира на 67 години.", "Широчината на релсите, която избира – 1435 мм, – и днес е стандартът в по-голямата част от света.", "Учи вечер, след като е работил целия ден в мините."],
  "Якоб Грим": ["Германски езиковед от Ханау, който с брат си Вилхелм събира народни приказки. Сред тях са „Снежанка“, „Пепеляшка“ и „Хензел и Гретел“. Започва огромния Немски речник и умира на 78 години в Берлин.", "Речникът, започнат от двамата братя, е завършен чак през 1961 г.", "Двамата са уволнени от университета в Гьотинген, защото протестират срещу краля."],
  "Луи Дагер": ["Френски художник на театрални декори, който изобретява дагеротипията – първия практичен начин за снимане. През 1839 г. Франция подарява изобретението на целия свят. Умира на 63 години.", "На една от първите му снимки на парижка улица има един-единствен човек – той стои неподвижно, докато му лъскат обувките.", "Преди фотографията прави „диорами“ – огромни картини, които се променят със светлината."],
  "Лорд Байрон": ["Английски поет, автор на „Дон Жуан“ и „Чайлд Харолд“, прочут и със скандалите си. Напуска Англия и отива да се бие за свободата на Гърция. Умира на 36 години от треска в Мисолонги и в Гърция е национален герой.", "В Кеймбридж забраняват кучета, затова той си държи мечка.", "Баща е на Ада Лъвлейс, първата програмистка."],
  "Самюъл Морз": ["Американски художник, който става изобретател. Създава електрическия телеграф и азбуката от точки и тирета, наречена на негово име. Първото му съобщение през 1844 г. е „Какво е сторил Бог!“. Умира на 80 години.", "Идеята му идва, след като съпругата му умира, докато е далеч, а вестта стига до него твърде късно.", "„SOS“ на морзовата азбука е три точки, три тирета, три точки."],
  "Майкъл Фарадей": ["Син на ковач от Лондон, почти без училище – чиракува като книговезец и чете книгите, които подвързва. Открива електромагнитната индукция и прави първия електромотор и динамо. Умира на 75 години.", "Започва коледни лекции за деца, които се изнасят и до днес.", "Отказва рицарска титла – иска да си остане „обикновеният господин Фарадей“."],
  "Франц Шуберт": ["Виенски композитор, който пише над 600 песни, сред тях „Горският цар“, съчинена на 17 години. Живее бедно, а приятелите му устройват вечери с неговата музика – „шубертиади“. Умира на 31 години и е погребан близо до Бетовен, както е искал.", "В един ден понякога пише по осем песни.", "Седмата му, „Недовършената“ симфония, има само две части."],
  "Александър Пушкин": ["Руски поет от Москва, създател на съвременната руска литература, автор на „Евгений Онегин“. Заради свободните си стихове е заточен на юг. Умира на 37 години след дуел, в който защитава честта на съпругата си.", "Прадядо му е африканец – Абрам Ганибал, кръщелник на Петър Велики.", "Пише и приказки в стихове, като „Приказка за рибаря и рибката“."],
  "Виктор Юго": ["Френски писател от Безансон, автор на „Клетниците“ и „Парижката Света Богородица“. Прекарва 19 години в изгнание на остров Гърнси, защото се противопоставя на Наполеон III. Умира на 83 години, а на погребението му излизат около два милиона души.", "След като „Клетниците“ излиза, пише на издателя си само „?“, а той отговаря само „!“.", "Романът му за „Парижката Света Богородица“ помага катедралата да бъде спасена от разрушение."],
  "Юстус фон Либих": ["Германски химик от Дармщат, който открива, че растенията се нуждаят от минерали, и така създава изкуствените торове. Въвежда обучение в лаборатория, по което учат химици от цял свят. Умира на 69 години в Мюнхен.", "Като чирак в аптека е изгонен, след като предизвиква експлозия.", "Измисля месния екстракт „Либих“, а към буркана му вървят прочути цветни картинки за колекциониране."],
  "Чарлз Дарвин": ["Английски природоизпитател, който пет години обикаля света с кораба „Бигъл“. През 1859 г. издава „Произход на видовете“ и обяснява как живите същества се променят чрез естествен подбор. Умира на 73 години и е погребан в Уестминстърското абатство.", "Костенурките и чинките от островите Галапагос му подсказват идеята.", "Изучава земните червеи десетилетия наред и пише цяла книга за тях."],
  "Ейбрахам Линкълн": ["Роден в дървена колиба в Кентъки, сам се изучава за адвокат. Като 16-и президент на САЩ води страната през Гражданската война и премахва робството. На 56 години е застрелян в театър „Форд“ във Вашингтон.", "Висок е 1,93 м – най-високият президент на САЩ.", "Единственият президент с патент – за уред, който повдига кораби над плитчини."],
  "Фредерик Шопен": ["Полски композитор и пианист, роден край Варшава, наречен „поета на пианото“. На 20 години напуска Полша и живее в Париж, където се свързва с писателката Жорж Санд. Умира на 39 години от туберкулоза.", "Сърцето му е занесено във Варшава в буркан с коняк и е зазидано в църквата „Свети Кръст“.", "Изнася първия си концерт на 7 години."],
  "Чарлз Дикенс": ["Английски писател, който като дете работи във фабрика за вакса, докато баща му е в затвора за длъжници. Пише „Оливър Туист“, „Дейвид Копърфийлд“ и „Коледна песен“. Умира на 58 години.", "„Коледна песен“ оформя начина, по който и днес празнуваме Коледа.", "Романите му излизат на части, а в Америка хората чакат на пристанището кораба със следващата част."],
  "Рихард Вагнер": ["Германски композитор от Лайпциг, автор на огромния оперен цикъл „Пръстенът на нибелунга“ – около 15 часа музика. С помощта на баварския крал Лудвиг II строи свой театър в Байройт. Умира на 69 години във Венеция.", "Сватбеният марш от неговата опера „Лоенгрин“ се свири на сватби по целия свят.", "Бяга от кредиторите си с кораб в страшна буря – и тя го вдъхновява за „Летящия холандец“."],
  "Ада Лъвлейс": ["Английска математичка, дъщеря на поета Байрон. Пише бележки към „Аналитичната машина“ на Чарлз Бабидж и в тях – първата компютърна програма. Умира на 36 години и е погребана до баща си, когото никога не е познавала.", "Предвижда, че един ден машините ще могат да пишат музика.", "Езикът за програмиране Ada носи нейното име."],
  "Ото фон Бисмарк": ["Пруски държавник, наречен „Железния канцлер“. През 1871 г. обединява Германия и става първият ѝ канцлер. Въвежда здравно осигуряване и пенсии – първите в света – и умира на 83 години.", "Като студент се бие в около 25 дуела.", "На негово име е кръстена мариновата херинга „Бисмарк“."],
  "Карл Маркс": ["Германски философ от Трир. С Фридрих Енгелс пише „Комунистическия манифест“, а после „Капиталът“. Живее години наред в бедност в Лондон и умира там на 64 години.", "На погребението му идват само около 11 души.", "Последният ред на манифеста е „Пролетарии от всички страни, съединявайте се!“."],
  "Кралица Виктория": ["Кралица на Великобритания 63 години – цяла епоха носи нейното име. Деветте ѝ деца се женят в кралските семейства на Европа и я наричат „бабата на Европа“. Умира на 81 години.", "Тя прави модерна бялата сватбена рокля.", "След смъртта на съпруга си Алберт носи черно 40 години."],
  "Джоузеф Базалгет": ["Английски инженер, който след „Голямата смрад“ в Лондон през 1858 г. строи канализацията на града. Над 1700 км тръби отвеждат мръсната вода и спират холерните епидемии. Умира на 71 години.", "Прави тръбите двойно по-широки, отколкото трябва – „ще го правим само веднъж“. Затова системата му работи и днес.", "Строи и крайбрежните булеварди по Темза."],
  "Флорънс Найтингейл": ["Английска медицинска сестра, кръстена на град Флоренция, където е родена. По време на Кримската война грижите ѝ спасяват хиляди ранени войници, а нощем обикаля с лампа – „Дамата с лампата“. Основава първото училище за медицински сестри и умира на 90 години.", "Международният ден на медицинската сестра е на нейния рожден ден, 12 май.", "Тя е и математичка – измисля нов вид диаграма, за да покаже от какво умират войниците."],
  "Георги Раковски": ["Революционер и писател от Котел, който пръв замисля организирана борба за освобождението на България. През 1862 г. създава Първата българска легия в Белград. Умира на 46 години от туберкулоза в Букурещ.", "Сменя имената си много пъти – роден е като Съби Стойков Попович.", "Пише поемата „Горски пътник“ – призив към българите да въстанат."],
  "Фьодор Достоевски": ["Руски писател от Москва, автор на „Престъпление и наказание“, „Идиот“ и „Братя Карамазови“. През 1849 г. е осъден на смърт, но е помилван в последния момент пред разстрелния взвод и прекарва четири години в каторга в Сибир. Умира на 59 години.", "Пише „Играчът“ за 26 дни, за да изплати дълговете си, и се жени за стенографката, на която го диктува.", "Цял живот се бори със страстта си към хазарта."],
  "Луи Пастьор": ["Френски учен, който доказва, че много болести се причиняват от микроби. Измисля пастьоризацията – затопляне, което пази млякото и виното от разваляне. През 1885 г. спасява момче, ухапано от бясно куче, с първата ваксина срещу бяс. Умира на 72 години.", "Три от петте му деца умират от тиф – това го кара да търси как да побеждава болестите.", "Спасеното момче, Жозеф Мейстер, по-късно става пазач в Института „Пастьор“."],
  "Грегор Мендел": ["Монах в манастир в Бърно, роден в Силезия. В манастирската градина отглежда около 28 000 растения грах и открива законите на наследствеността. Никой не разбира откритието му приживе; умира на 61 години като игумен.", "Два пъти се проваля на изпита за учител.", "Трудът му е преоткрит чак през 1900 г. и той става „бащата на генетиката“."],
  "Лев Толстой": ["Руски писател, роден в имението Ясна поляна, автор на „Война и мир“ и „Ана Каренина“. На стари години проповядва простия живот и ненасилието и вдъхновява Ганди. На 82 години тайно напуска дома си и умира на малка железопътна гара.", "Съпругата му преписва „Война и мир“ на ръка около седем пъти.", "В „Война и мир“ има около 580 героя."],
  "Дмитрий Менделеев": ["Руски химик от Тоболск в Сибир, най-малкото от много деца. През 1869 г. подрежда химичните елементи в таблица и оставя празни места за още неоткрити – и те наистина се откриват. Умира на 72 години.", "Според легендата вижда таблицата насън.", "Елемент номер 101 се казва менделевий."],
  "Марк Твен": ["Американски писател, истинско име Самюъл Клемънс, израснал на брега на Мисисипи. Работи като лоцман на параход, после пише „Приключенията на Том Сойер“ и „Хъкълбери Фин“. Умира на 74 години.", "Роден е в годината на Халеевата комета и предсказва, че ще си отиде с нея – и умира при следващото ѝ идване, през 1910 г.", "„Марк Твен“ е викът на лоцманите за дълбочина от два фатома."],
  "Васил Левски": ["Роден в Карлово като Васил Кунчев, бивш монах, наричан Дякона. Обикаля страната и създава мрежа от тайни революционни комитети за освобождението на България. Заловен е край Ловеч и обесен в София на 35 години.", "Наричат го „Апостола на свободата“.", "Прякорът „Левски“ получава, защото прескача като лъв."],
  "Пьотр Чайковски": ["Руски композитор, автор на балетите „Лебедово езеро“, „Лешникотрошачката“ и „Спящата красавица“. Цели 13 години го подкрепя с пари богата почитателка, с която само си пишат писма и никога не се срещат. Умира на 53 години в Санкт Петербург.", "Дирижира на откриването на „Карнеги Хол“ в Ню Йорк през 1891 г.", "Като малък се разплаква, когато чува музика, и казва: „Тази музика е в главата ми и не ме оставя!“"],
  "Клод Моне": ["Френски художник от Париж, бащата на импресионизма. Цялото течение е кръстено на неговата картина „Импресия. Изгрев“. Последните си години рисува водните лилии в градината си в Живерни и умира на 86 години.", "Рисува около 250 картини с водни лилии.", "На стари години перде на очите променя цветовете, които вижда – и картините му стават по-червени."],
  "Роберт Кох": ["Германски лекар, който открива бактериите, причиняващи антракс, туберкулоза и холера. През 1905 г. получава Нобелова награда. Умира на 66 години в Баден-Баден.", "Световният ден за борба с туберкулозата, 24 март, е денят, в който обявява откритието си.", "Започва като селски лекар с микроскоп, подарен му от съпругата му."],
  "Карл Бенц": ["Германски инженер от Карлсруе, който през 1886 г. патентова първия истински автомобил с бензинов двигател. Компанията му по-късно става „Мерцедес-Бенц“. Умира на 84 години.", "Баща му, машинист на локомотив, умира, когато Карл е на 2 години.", "Първата му кола има само три колела."],
  "Фридрих Ницше": ["Германски философ, станал професор в Базел едва на 24 години. Пише „Тъй рече Заратустра“ и прочутото „Бог е мъртъв“. През 1889 г. в Торино рухва психически и последните си 11 години прекарва болен; умира на 55.", "Според разказите при срива си прегръща кон, който бият на улицата.", "Композира и музика."],
  "Вилхелм Рьонтген": ["Германски физик, който през 1895 г. открива лъчите, виждащи през тялото – рентгеновите. През 1901 г. получава първата Нобелова награда за физика в историята. Умира на 77 години.", "Първата рентгенова снимка е на ръката на съпругата му – с пръстена ѝ.", "Отказва да патентова откритието си, за да е от полза на всички."],
  "Томас Едисон": ["Американски изобретател с над 1000 патента – фонографа, практичната електрическа крушка, кинокамерата и първите електроцентрали. Ходи на училище едва три месеца. Умира на 84 години.", "Почти глух е от младини.", "Казва: „Геният е един процент вдъхновение и деветдесет и девет процента пот.“"],
  "Христо Ботев": ["Поет и революционер от Калофер. В Румъния издава вестници и пише стихове за свободата. През 1876 г. с чета превзема австрийския параход „Радецки“, слиза при Козлодуй и загива на 28 години във Врачанския Балкан.", "Всяка година на 2 юни в 12 часа сирените в България вият една минута в негова памет и в памет на загиналите за свободата.", "Копие на парахода „Радецки“ днес стои в Козлодуй."],
  "Берта Бенц": ["Съпругата на Карл Бенц, която влага зестрата си в неговия автомобил. През 1888 г., без да каже на мъжа си, тръгва с двамата им сина на първото дълго пътуване с кола – 106 км от Манхайм до Пфорцхайм. Умира на 95 години.", "По пътя прочиства запушена тръба с карфица за шапка и изолира кабел с жартиера си.", "Купува бензин от аптека във Вислох – днес тя се смята за първата бензиностанция в света."],
  "Иван Вазов": ["Писател от Сопот, наречен „патриарх на българската литература“. В изгнание в Одеса пише „Под игото“ – първия български роман – и „Епопея на забравените“. Бил е и министър на просвещението. Умира на 71 години в София.", "„Под игото“ е преведен на над 30 езика.", "Никога не се жени."],
  "Винсент ван Гог": ["Холандски художник, който рисува около 900 картини само за десетина години, сред тях „Слънчогледи“ и „Звездна нощ“. Живее бедно и страда от тежки душевни кризи, в една от които отрязва част от ухото си. Умира на 37 години от огнестрелна рана.", "Приживе продава само една картина.", "Написва над 650 писма на брат си Тео, който цял живот го подкрепя."],
  "Никола Тесла": ["Роден в Смилян, в днешна Хърватия. Изобретява системата за променлив ток, която и днес захранва домовете ни. Умира беден и сам в хотелска стая в Ню Йорк на 86 години.", "Единицата за магнитна индукция „тесла“ носи неговото име.", "Обича гълъбите и се грижи за тях до края на живота си."],
  "Зигмунд Фройд": ["Австрийски лекар, роден в Моравия, който живее във Виена. Създава психоанализата и учи, че сънищата и несъзнаваното управляват голяма част от живота ни. През 1938 г. бяга от нацистите в Лондон и умира там на 83 години.", "Прочутото му канапе за пациенти днес е в музея му в Лондон.", "Пуши по около 20 пури на ден."],
  "Макс Планк": ["Германски физик от Кил, който през 1900 г. поставя началото на квантовата теория. През 1918 г. получава Нобелова награда. Умира на 89 години.", "Учителят му го съветва да не учи физика, защото в нея „почти всичко вече е открито“.", "Свири отлично на пиано и често музицира с Айнщайн."],
  "Алеко Константинов": ["Писател от Свищов, когото наричат Щастливеца. Създава Бай Ганьо и пише пътеписа „До Чикаго и назад“ след посещение на Световното изложение. На 34 години е убит по погрешка край Пазарджик – куршумът е бил за друг.", "През 1895 г. води около 300 души на Черни връх и така поставя началото на организирания туризъм в България.", "Бай Ганьо става толкова популярен, че името му е нарицателно и до днес."],
  "Мария Кюри": ["Родена във Варшава, открива полония и радия заедно със съпруга си Пиер. Първата жена с Нобелова награда и единственият човек с две Нобелови награди в различни науки – физика и химия. Умира на 66 години от болест, причинена от радиацията, с която е работила.", "Нарича полония на родината си Полша.", "Тетрадките ѝ и днес са радиоактивни и се пазят в оловни кутии."],
  "Махатма Ганди": ["Индийски адвокат, който в Южна Африка и после в Индия води борба без насилие срещу несправедливостта. През 1930 г. извървява пеша 385 км до морето в „Похода на солта“. Индия става независима през 1947 г., а на следващата година той е убит на 78 години.", "Номиниран е пет пъти за Нобелова награда за мир, но не я получава.", "Сам преде платното за дрехите си."],
  "Орвил Райт": ["Американец, който с брат си Уилбър поправя велосипеди в Дейтън и строи самолети. На 17 декември 1903 г. Орвил пилотира първия управляем полет с мотор – 12 секунди и 37 метра. Умира на 76 години.", "Нийл Армстронг отнася парче от плата на самолета им на Луната.", "Нито един от двамата братя не се жени."],
  "Гулиелмо Маркони": ["Италиански изобретател от Болоня, който създава радиото. През 1901 г. изпраща радиосигнал през Атлантическия океан. На 35 години получава Нобелова награда и умира на 63.", "Оцелелите от „Титаник“ са спасени, защото корабът праща сигнал за помощ с неговото радио.", "При смъртта му радиостанциите по целия свят замлъкват за две минути."],
  "Уинстън Чърчил": ["Британски държавник, роден в двореца Бленъм. Като министър-председател води Великобритания през Втората световна война с речта си „Нищо друго освен кръв, труд, сълзи и пот“. Получава Нобелова награда за литература и умира на 90 години.", "Като млад журналист бяга от плен по време на Бурската война.", "Рисува около 500 картини."],
  "Томас Ман": ["Германски писател от Любек, автор на „Буденброкови“ и „Вълшебната планина“. През 1929 г. получава Нобелова награда. Противник на нацистите, емигрира в САЩ и умира на 80 години в Цюрих.", "Пише „Буденброкови“ едва на 25 години.", "Цялото му семейство пише – брат му Хайнрих и децата му Клаус и Ерика също са писатели."],
  "Елин Пелин": ["Писател от село Байлово, истинско име Димитър Иванов Стоянов. Майстор на разказа за селския живот – „Гераците“, „Андрешко“ – и автор на детските книги за Ян Бибиян. Умира на 72 години в София.", "В продължението Ян Бибиян отлита чак до Луната.", "Дълги години работи като уредник в Университетската библиотека."],
  "Пейо Яворов": ["Поет от Чирпан, роден като Пейо Крачолов. Участва в четите в Македония и пише едни от най-силните български стихове за любовта и тъгата. След трагичната смърт на съпругата си Лора губи зрението си и на 36 години слага край на живота си.", "Името „Яворов“ взема от дървото явор.", "Пише стихотворението „Две хубави очи“, станало прочута песен."],
  "Алберт Айнщайн": ["Физик от Улм, създател на теорията на относителността и формулата E = mc². През 1921 г. получава Нобелова награда, а през 1933 г. емигрира в САЩ. Умира на 76 години в Принстън.", "Не е вярно, че е бил слаб по математика – това е мит.", "През 1952 г. му предлагат да стане президент на Израел, но той отказва."],
  "Александър Флеминг": ["Шотландски лекар и учен. През 1928 г., след като се връща от отпуска, вижда плесен в забравена петриева паничка, около която бактериите са умрели – така открива пеницилина. През 1945 г. получава Нобелова награда и умира на 73 години.", "Пеницилинът и антибиотиците след него спасяват стотици милиони животи.", "По-рано открива вещество срещу бактерии в собствените си сополи."],
  "Пабло Пикасо": ["Испански художник от Малага, създател на кубизма заедно с Брак. Рисува „Герника“ – вик срещу бомбардировката на един град. Създава около 50 000 творби и умира на 91 години.", "Първата му дума е „пис“ – от „лапис“, молив.", "Пълното му име съдържа над 20 имена на светци и роднини."],
  "Франц Кафка": ["Писател от Прага, който пише на немски, докато работи като чиновник в застрахователна компания. Автор на „Преображението“ – за човек, който една сутрин се събужда като огромно насекомо – и „Процесът“. Умира на 40 години от туберкулоза.", "Моли приятеля си Макс Брод да изгори всичките му ръкописи, но той ги издава.", "От името му идва думата „кафкиански“ – за безсмислено и плашещо положение."],
  "Чарли Чаплин": ["Актьор и режисьор, израснал в бедност в Лондон. Създава Скитника с бастунчето и бомбето – най-известния герой на нямото кино. В „Великият диктатор“ осмива Хитлер. Умира на 88 години в Швейцария на Коледа.", "През 1978 г. ковчегът му е откраднат за откуп и намерен след няколко седмици.", "Казват, че веднъж участва в конкурс за двойници на Чаплин – и не печели."],
  "Агата Кристи": ["Английска писателка от Торки, най-продаваният автор на романи в историята. Създава детективите Еркюл Поаро и мис Марпъл. Пиесата ѝ „Капан за мишки“ се играе без прекъсване от 1952 г. Умира на 85 години.", "През 1926 г. изчезва за 11 дни и до днес никой не знае със сигурност какво се е случило.", "Работи в болнична аптека и затова знае толкова много за отровите."],
  "Дж. Р. Р. Толкин": ["Роден в Блумфонтейн, Южна Африка, професор в Оксфорд. Пише „Хобитът“ и „Властелинът на пръстените“ и измисля цели езици за елфите. Умира на 81 години.", "Първото изречение на „Хобитът“ – „В една дупка в земята живееше хобит“ – надрасква върху празен лист, докато проверява изпитни работи.", "Като млад се бие в битката при Сома в Първата световна война."],
  "Елисавета Багряна": ["Поетеса от София, истинско име Елисавета Белчева. Стиховете ѝ за свободата, морето и жената – „Вечната и святата“, „Потомка“ – я правят най-обичаната българска поетеса. Умира на 97 години.", "Псевдонимът „Багряна“ идва от „багрен“ – алено червен.", "Номинирана е за Нобелова награда за литература."],
  "Марлене Дитрих": ["Германска актриса и певица от Берлин, станала звезда с филма „Синият ангел“. Отказва да работи за нацистите, става американка и пее пред войниците на фронта. Умира на 90 години в Париж.", "Песента „Лили Марлен“ в нейно изпълнение обича войниците и от двете страни на фронта.", "Шокира публиката, като носи панталони, когато това не е прието за жени."],
  "Уолт Дисни": ["Американски аниматор от Чикаго, създател на Мики Маус през 1928 г. и на „Снежанка“ – първия пълнометражен анимационен филм. Открива Дисниленд през 1955 г. и умира на 65 години.", "Самият той дава гласа на Мики Маус.", "Има 22 награди „Оскар“ – повече от всеки друг човек."],
  "Джордж Оруел": ["Английски писател, роден в Индия като Ерик Блеър. Пише „Фермата на животните“ и „1984“ – книги срещу тиранията. Бие се в Испанската гражданска война и е ранен в гърлото. Умира на 46 години от туберкулоза.", "Изразът „Големия брат те наблюдава“ идва от „1984“.", "Пише „1984“ на отдалечен шотландски остров, вече тежко болен."],
  "Сергей Корольов": ["Съветски конструктор на ракети, роден в Житомир. Като главен конструктор изпраща в космоса първия спътник през 1957 г. и Юрий Гагарин през 1961 г. Умира на 59 години по време на операция.", "Докато е жив, името му е държавна тайна – наричат го само „Главния конструктор“.", "Преди това прекарва години в лагер в Сибир, обвинен несправедливо."],
  "Фрида Кало": ["Мексиканска художничка от Койоакан. На 18 години катастрофа с автобус ѝ причинява болки за цял живот, а в леглото започва да рисува. Повечето ѝ картини са автопортрети. Умира на 47 години.", "Домът ѝ, „Синята къща“, днес е музей.", "Последната ѝ картина, натюрморт с дини, носи надписа „Да живее животът“."],
  "Никола Вапцаров": ["Поет от Банско, завършил морско училище и работил като огняр на кораби и машинист. Единствената му стихосбирка, „Моторни песни“, е за труда и вярата в човека. Разстрелян е на 32 години за участие в съпротивата.", "Часове преди разстрела пише последното си стихотворение – „Борбата е безмилостно жестока“.", "Връх в Антарктида носи неговото име."],
  "Конрад Цузе": ["Германски инженер от Берлин, който през 1941 г. построява Z3 – първия работещ програмируем компютър. Първите си машини сглобява в хола на родителите си. Умира на 85 години.", "Измисля и Plankalkül – първия език за програмиране от високо ниво.", "Освен инженер е и художник."],
  "Майка Тереза": ["Родена в Скопие като Анджезе Бояджиу, монахиня, която посвещава живота си на най-бедните в Калкута. Основава ордена „Мисионерки на милосърдието“. През 1979 г. получава Нобелова награда за мир и умира на 87 години; обявена е за светица.", "Моли банкетът за Нобеловата награда да бъде отменен и парите да отидат за бедните.", "Носи бяло сари със сини ивици, което става знак на ордена ѝ."],
  "Ванга": ["Българска ясновидка от Струмица, ослепяла като дете след буря. Живее в Петрич, а при нея идват десетки хиляди хора – от селяни до държавници. Умира през 1996 г. на 85 години.", "Държавата ѝ плаща заплата като служител на институт, който изучава способностите ѝ.", "Около името ѝ се разпространяват много „предсказания“, които тя никога не е казвала."],
  "Алън Тюринг": ["Английски математик, баща на информатиката. Описва „машината на Тюринг“ – идеята за компютъра, а през Втората световна война помага да се разбие германската шифровъчна машина „Енигма“. Осъден е за хомосексуалност и умира от отравяне с цианид на 41 години.", "Измисля „теста на Тюринг“ – дали машина може да се представи за човек в разговор.", "Тича маратон за 2 ч. и 46 мин. и почти влиза в олимпийския отбор."],
  "Вернер фон Браун": ["Германски ракетен инженер. Създава ракетата Фау-2 за нацистка Германия, а след войната е отведен в САЩ, където конструира ракетата „Сатурн V“, която отнася хората до Луната. Умира през 1977 г. на 65 години.", "Фау-2 е произвеждана от затворници в ужасни условия – повече хора загиват при направата ѝ, отколкото от ударите ѝ.", "Като момче завързва ракети за количка и я пуска по улицата в Берлин – полицията го прибира."],
  "Роза Паркс": ["Афроамериканска шивачка от Монтгомъри, Алабама. През 1955 г. отказва да отстъпи мястото си в автобуса на бял пътник и е арестувана. Последва бойкот на автобусите, който става начало на движението за граждански права. Умира през 2005 г. на 92 години.", "Бойкотът продължава 381 дни, докато сегрегацията в автобусите не е забранена.", "След смъртта ѝ тялото ѝ е изложено в Капитолия – първата жена с тази почит."],
  "Норман Борлоуг": ["Американски агроном, баща на „Зелената революция“. Създава нисък и устойчив сорт пшеница, който удвоява и утроява реколтите в Мексико, Индия и Пакистан. Получава Нобелова награда за мир през 1970 г. и умира на 95 години.", "Смята се, че работата му спасява от глад около милиард души.", "Научава за наградата си на полето – жена му кара до там, за да му каже."],
  "Нелсън Мандела": ["Южноафрикански борец срещу апартейда. Прекарва 27 години в затвора, а след освобождаването си през 1990 г. става първият чернокож президент на ЮАР и помирява страната. Умира през 2013 г. на 95 години.", "Повечето от годините в затвора прекарва на остров Робен, където чупи камъни в кариера.", "Нобеловата награда за мир за 1993 г. дели с президента, който го освобождава – Фредерик де Клерк."],
  "Йоан Павел II": ["Карол Войтила, първият папа поляк и първият неиталианец от 455 години. Папа е от 1978 до 2005 г., пътува по целия свят и помага за падането на комунизма в Източна Европа. Умира на 84 години.", "През 1981 г. оцелява след покушение и по-късно прощава на стрелеца в затвора.", "Като млад е актьор и пише пиеси."],
  "Софи Шол": ["Германска студентка от Мюнхен, член на групата „Бялата роза“, която разпространява позиви срещу Хитлер. През 1943 г. е хваната да хвърля позиви в университета и е обезглавена на 21 години, заедно с брат си Ханс.", "Само няколко дни делят ареста ѝ от екзекуцията.", "Последният позив на групата е пренесен до Англия, а британски самолети го хвърлят над Германия в милиони копия."],
  "Мартин Лутър Кинг": ["Американски пастор и водач на движението за граждански права на чернокожите. Проповядва ненасилие и през 1963 г. произнася речта „Имам една мечта“. Получава Нобелова награда за мир и е застрелян през 1968 г. на 39 години.", "На 35 години е най-младият носител на Нобеловата награда за мир дотогава.", "Рожденото му име е Майкъл – баща му сменя имената и на двамата след пътуване до Германия."],
  "Ана Франк": ["Еврейско момиче от Франкфурт, чието семейство бяга в Амстердам. Две години се крие с тях в таен заден дом и води дневник. През 1944 г. са предадени, а тя умира от тиф в лагера Берген-Белзен на 15 години.", "Баща ѝ е единственият оцелял от осемте скрити и той издава дневника.", "Получава дневника за 13-ия си рожден ден и го нарича „Кити“."],
  "Нийл Армстронг": ["Американски астронавт и пилот изпитател. На 20 юли 1969 г. с „Аполо 11“ става първият човек, стъпил на Луната. Умира през 2012 г. на 82 години.", "Първите му думи там: „Една малка крачка за човека, един огромен скок за човечеството.“", "Отпечатъците от стъпките му вероятно още са там – на Луната няма вятър."],
  "Юрий Гагарин": ["Съветски летец, син на колхозници. На 12 април 1961 г. с „Восток 1“ става първият човек в космоса – обикаля Земята за 108 минути. Загива при тренировъчен полет с изтребител през 1968 г. на 34 години.", "При излитането казва „Поехали!“ – „Тръгваме!“.", "Каца с парашут в поле и плаши една селянка и внучката ѝ."],
  "Елвис Пресли": ["Американски певец от Мисисипи, „кралят на рокендрола“. От шофьор на камион става най-голямата звезда на 50-те години с песни като „Hound Dog“. Умира в дома си Грейсланд през 1977 г. на 42 години.", "Има брат близнак, Джеси, който умира при раждането.", "Продал е над половин милиард записа."],
  "Джон Ленън": ["Английски музикант от Ливърпул, основател на „Бийтълс“. След разпадането на групата пише песента „Imagine“ и се бори за мир заедно с Йоко Оно. Застрелян е пред дома си в Ню Йорк през 1980 г. на 40 години.", "Убиецът му взима автограф от него само няколко часа по-рано.", "Учителите му пишат, че е „на път към провала“."],
  "Стивън Хокинг": ["Британски физик, изучавал черните дупки и началото на Вселената. На 21 години се разболява от ALS и лекарите му дават две години живот, но той живее още 55, говорейки чрез компютър. Умира през 2018 г. на 76 години.", "Книгата му „Кратка история на времето“ е продадена в над 10 милиона копия.", "Роден е точно 300 години след смъртта на Галилей, а умира на рождения ден на Айнщайн."],
  "Мохамед Али": ["Американски боксьор, роден като Касиус Клей. Три пъти световен шампион в тежка категория, известен с бързината си и с думите „Лети като пеперуда, жили като пчела“. Отказва да воюва във Виетнам. Умира през 2016 г. на 74 години.", "Започва бокс на 12 години, защото му крадат колелото и иска да набие крадеца.", "Заради отказа си да служи му взимат титлата и не се бие почти четири години."],
  "Фреди Меркюри": ["Певец на британската група „Куийн“, роден като Фарох Булсара в Занзибар. Автор на „Bohemian Rhapsody“ и „We Are the Champions“, с глас в четири октави. Умира от СПИН през 1991 г. на 45 години.", "Сам рисува герба на групата, защото учи графичен дизайн.", "Изпълнението им на „Live Aid“ през 1985 г. често е наричано най-доброто концертно изпълнение в историята."],
  "Стив Джобс": ["Американски предприемач, основател на Apple заедно със Стив Возняк в един гараж. Изгонен е от собствената си компания, после се връща и създава iPod, iPhone и iPad. Умира от рак на панкреаса през 2011 г. на 56 години.", "Осиновен е като бебе – биологичният му баща е от Сирия.", "Купува малко студио, което става Pixar и прави „Играта на играчките“."],
  "Хатшепсут": ["Египетска царица, която се обявява за фараон и управлява около 20 години в мир и богатство. Строи великолепния храм в Дейр ел-Бахри и праща експедиция до далечната страна Пунт. Умира на около 49 години.", "На статуите често е изобразена с фалшива фараонска брада.", "След смъртта ѝ някой старателно изтрива името и образите ѝ от паметниците."],
  "Кир Велики": ["Основател на Персийската империя, най-голямата дотогава – от Средиземно море до Индия. Превзема Мидия, Лидия и Вавилон, но се отнася търпимо към покорените народи. Загива в битка около 530 г. пр. Хр. на около 70 години.", "Позволява на евреите да се върнат от вавилонския плен и да построят храма си отново.", "Глинен цилиндър с неговите думи понякога е наричан „първата харта за човешки права“."],
  "Дарий I": ["Персийски цар, който подрежда огромната империя: разделя я на провинции, въвежда обща монета и строи Царския път от 2700 км. Нахлува в Гърция, но е победен при Маратон. Умира през 486 г. пр. Хр. на 64 години.", "По Царския път вестоносците минават за седмица разстояние, за което другите вървят три месеца.", "Строи нов блестящ град – Персеполис."],
  "Сун Дзъ": ["Китайски пълководец и мислител, на когото се приписва книгата „Изкуството на войната“. Служи на царството У. За живота му се знае много малко; смята се, че умира на около 48 години.", "Най-известната му мисъл: най-добрата победа е да победиш врага без битка.", "Книгата му днес се чете от бизнесмени и спортни треньори."],
  "Темистокъл": ["Атински политик и пълководец. Убеждава атиняните да построят флот със сребро от мините и с него побеждава персите при Саламин през 480 г. пр. Хр. По-късно е изгонен от Атина и умира в Персия на 65 години.", "Атиняните използват парите от новата сребърна жила за кораби, вместо да си ги разделят.", "Накрая служи на същия персийски цар, чийто баща е победил."],
  "Тукидид": ["Атински историк и пълководец. Описва Пелопонеската война между Атина и Спарта, като търси истинските причини, а не волята на боговете. Умира около 400 г. пр. Хр. на около 60 години.", "Сам преживява чумата в Атина и я описва подробно.", "Пише книгата в изгнание, след като като военачалник не успява да спаси един град."],
  "Аристофан": ["Атински автор на комедии. В пиеси като „Облаците“, „Птиците“ и „Лизистрата“ осмива политици, философи и войната. Умира около 386 г. пр. Хр. на около 60 години.", "В „Лизистрата“ жените спират войната, като отказват на мъжете си.", "В „Облаците“ осмива Сократ, който седи в кош, окачен във въздуха."],
  "Диоген": ["Гръцки философ киник, който живее в бедност и пренебрегва всякакви обичаи. Спи в голяма глинена делва в Атина и учи, че щастието е в простия живот. Умира в Коринт на около 89 години.", "Посред бял ден обикаля с фенер и казва, че „търси човек“.", "Когато Александър Велики го пита какво иска, Диоген отвръща: „Отмести се, пречиш ми на слънцето.“"],
  "Ератостен": ["Гръцки учен, ръководител на Александрийската библиотека. Измерва обиколката на Земята по сенките в два града и почти уцелва истинската стойност. Умира около 194 г. пр. Хр. на 82 години.", "Измисля „решетото на Ератостен“ за намиране на прости числа.", "Пръв използва думата „география“."],
  "Сципион Африкански": ["Римски пълководец, който побеждава Ханибал при Зама през 202 г. пр. Хр. и слага край на Втората пуническа война. По-късно е обвинен от политически врагове и се оттегля в имението си, където умира на 53 години.", "Командва армия още на 25 години, много под законовата възраст.", "Нарежда на гроба му да пише: „Неблагодарно отечество, няма да имаш дори костите ми.“"],
  "Помпей Велики": ["Римски пълководец, прочистил Средиземно море от пирати и завладял Изтока. Първо съюзник, а после враг на Юлий Цезар; губи гражданската война и бяга в Египет, където е убит през 48 г. пр. Хр. на 57 години.", "Справя се с пиратите за около три месеца.", "Строи първия каменен театър в Рим – там по-късно е убит Цезар."],
  "Арминий": ["Германски вожд от племето херуски, който служи в римската армия. През 9 г. в Тевтобургската гора примамва три римски легиона в засада и ги унищожава. Убит е от свои роднини на около 38 години.", "След поражението император Август вика: „Вар, върни ми легионите!“", "В Германия го наричат Херман, а паметникът му е висок над 50 метра."],
  "Сенека": ["Римски философ стоик, писател и учител на император Нерон. Пише писма за спокойствието, времето и смъртта, които се четат и до днес. Нерон го обвинява в заговор и му заповядва да се самоубие; умира през 65 г. на 68 години.", "Едно време е най-влиятелният човек в Рим до младия Нерон.", "Казва: „Не ни е дадено малко време, а губим много.“"],
  "Плиний Стари": ["Римски учен, писател и командир на флота. Написва „Естествена история“ – огромна енциклопедия за всичко познато тогава. Загива през 79 г. на 56 години, докато се опитва да спаси хора при изригването на Везувий.", "Работи дори в банята и по време на хранене – някой му чете на глас.", "Племенникът му Плиний Млади описва изригването в писмо – така то става първото подробно описание на вулкан."],
  "Будика": ["Кралица на британското племе ицени. След като римляните заграбват земите ѝ и посрамват семейството ѝ, през 60 г. вдига въстание и опожарява Лондиниум. Победена е от римската армия и умира на около 31 години – вероятно отровена от собствената си ръка.", "Въстаналите опожаряват три града, сред тях бъдещия Лондон.", "Бронзовата ѝ статуя с бойна колесница стои до британския парламент."],
  "Цай Лун": ["Китайски придворен служител при династията Хан. Около 105 г. подобрява и описва направата на хартия от кора, стари парцали и рибарски мрежи. Замесен в дворцови интриги, той се самоубива на около 71 години.", "Преди хартията китайците пишат върху бамбукови плочки и скъпа коприна.", "Тайната на хартията стига до Европа чак след около хиляда години."],
  "Траян": ["Римски император, роден в Испания. При него империята е най-голяма – той покорява Дакия и стига до Персийския залив. Строи пазари, мостове и пътища. Умира през 117 г. на 63 години.", "Колоната на Траян в Рим разказва войната с даките в над 2500 фигури.", "В днешна България градовете Никополис ад Иструм и Улпия Ескус носят неговото име."],
  "Адриан": ["Римски император, който спира завоеванията и укрепява границите. Обикаля цялата империя и строи Адриановия вал в Британия и Пантеона в Рим. Умира през 138 г. на 62 години.", "Първият император с брада – модата я следва цял век.", "Одрин (Адрианопол) е основан от него и носи името му."],
  "Гален": ["Гръцки лекар от Пергам, работил в Рим като лекар на императори. Изследва анатомията, като разрязва животни, и пише стотици трудове. Неговите учения управляват медицината почти 1400 години. Умира на около 87 години.", "Като млад лекува ранени гладиатори.", "Доказва, че по артериите тече кръв, а не въздух, както се смята дотогава."],
  "Диоклециан": ["Римски император, син на освободен роб. Разделя империята между четирима владетели и реформира данъците и армията; жестоко преследва християните. През 305 г. доброволно се оттегля и отглежда зеле в двореца си в Сплит. Умира на около 66 години.", "Единственият римски император, който се оттегля доброволно.", "Когато го молят да се върне на власт, казва, че ако видят зелето му, няма да го молят."],
  "Свети Николай Чудотворец": ["Епископ на град Мира в Мала Азия, известен с милосърдието си. Помага тайно на бедни и защитава невинни. Умира около 343 г. на около 73 години и става един от най-почитаните светци – покровител на моряците и рибарите.", "Тайно хвърля торбички злато в дома на беден баща, за да омъжи дъщерите си – оттам идва Дядо Коледа (Санта Клаус).", "В България Никулден се празнува с рибна чорба и шаран."],
  "Свети Патрик": ["Покръстител на Ирландия, роден в римска Британия. На 16 години е отвлечен от пирати и шест години пасе овце като роб в Ирландия, после бяга. Връща се като мисионер и покръства ирландците. Умира на около 76 години.", "Обяснява Светата Троица с трилистна детелина – тя става символ на Ирландия.", "Денят му, 17 март, се празнува по целия свят със зелено."],
  "Теодорих Велики": ["Крал на остготите, който като дете е заложник в Константинопол. Завладява Италия и я управлява над 30 години мирно, като пази римските закони. Умира в Равена през 526 г. на 72 години.", "Като млад живее и воюва и в днешна България – около Нове край Свищов.", "В германските легенди е героят Дитрих фон Берн."],
  "Хлодвиг I": ["Крал на франките, който обединява Галия и основава франкската държава. Около 500 г. приема християнството и с това печели подкрепата на църквата. Прави Париж своя столица и умира през 511 г. на 45 години.", "Името Хлодвиг по-късно се превръща в Луи – името на 18 френски крале.", "Покръстен е заедно с 3000 свои воини."],
  "Свети Бенедикт": ["Италиански монах, който основава манастира Монте Касино. Пише „Устава“ – правила за живота на монасите в молитва и труд, по които живеят хиляди манастири. Умира около 547 г. на 67 години и е покровител на Европа.", "Мотото на монасите му е „Ора ет лабора“ – „Моли се и работи“.", "Като млад живее три години сам в пещера."],
  "Императрица Теодора": ["Византийска императрица, съпруга на Юстиниан. От актриса и дъщеря на пазач на мечки става една от най-могъщите жени в историята. По време на бунта „Ника“ убеждава съпруга си да не бяга. Умира през 548 г. на 48 години.", "Казва, че „царската багреница е добър саван“ – по-добре да умреш император, отколкото да избягаш.", "Прокарва закони в защита на жените."],
  "Хан Кубрат": ["Владетел от рода Дуло, който обединява прабългарите и около 632 г. създава Стара Велика България край Черно и Азовско море. Като млад живее в Константинопол и е приятел на император Ираклий. Умира около 665 г. на около 60 години.", "Според легендата преди смъртта си дава на синовете си сноп пръчки: заедно не се чупят, поотделно – лесно.", "Гробът му вероятно е намерен при Перешчепино в Украйна – с над 20 кг злато."],
  "Ву Дзътиен": ["Единствената жена в историята на Китай, управлявала като императрица от свое име. От наложница става съпруга на императора, а после сама основава династия. Умира през 705 г. на 81 години.", "Насърчава изпитите за чиновници, така че и хора без знатен род да стигат до властта.", "Измисля над десет нови йероглифа, включително за собственото си име."],
  "Хан Тервел": ["Български хан, син на Аспарух. През 705 г. помага на сваления император Юстиниан II да си върне трона и получава титлата „кесар“ и земи. През 717–718 г. помага на Византия да разбие арабите пред Константинопол. Умира около 721 г. на около 46 години.", "Първият чужденец, получил византийската титла кесар.", "Наричат го „спасителя на Европа“, защото спира арабите пред Константинопол."],
  "Харун ар-Рашид": ["Абасидски халиф в Багдад, при когото халифатът е в разцвета си. Подкрепя учените, поетите и търговията, а Багдад става най-големият град на света. Умира през 809 г. на 46 години.", "Появява се в приказките от „Хиляда и една нощ“, където се разхожда преоблечен из Багдад.", "Изпраща на Карл Велики подарък слон на име Абул Абас и сложен воден часовник."],
  "Хан Омуртаг": ["Български хан, син на Крум. Сключва 30-годишен мир с Византия и се заема със строеж: дворци, крепости и мостове. Оставя много надписи на гръцки. Умира около 831 г. на около 41 години.", "В надпис пише: „Човек и добре да живее, умира, и друг се ражда.“", "Строи нов дворец на Дунав и прочутия аул край Плиска."],
  "Свети Наум Охридски": ["Ученик на Кирил и Методий. След смъртта на Методий идва в България, работи в Плиска и Преслав, а после в Охрид. Основава манастир на брега на Охридското езеро и умира там през 910 г. на около 80 години.", "Според легендата впряга мечка в ралото, след като тя изяжда вола му.", "Манастирът „Свети Наум“ и днес е място за поклонение."],
  "Свети Климент Охридски": ["Ученик на Кирил и Методий, един от най-големите български книжовници. Изпратен е в Кутмичевица (Охрид), където обучава над 3500 ученици и пише много проповеди. Става първият епископ на български език и умира през 916 г. на около 76 години.", "Смята се, че създава кирилицата като опростява глаголицата и я доближава до гръцкото писмо.", "Софийският университет носи неговото име."],
  "Цар Самуил": ["Български цар, който десетилетия защитава държавата от император Василий II. Столицата му е в Охрид. През 1014 г. войската му е разбита при Беласица, а Василий ослепява хилядите пленници. Умира от удар скоро след това, на 56 години.", "На всеки сто ослепени оставят по един с едно око, за да ги води до вкъщи.", "Василий II получава прякора „Българоубиец“."],
  "Лейф Ериксон": ["Исландски викинг, син на Ерик Червения. Около 1000 г. стига до Северна Америка – близо 500 години преди Колумб – и я нарича Винланд. Умира около 1020 г. на около 50 години.", "Останки от викингско селище са намерени в Нюфаундленд, Канада.", "Винланд значи „страна на лозата“ – там намират диво грозде."],
  "Уилям Завоевателя": ["Херцог на Нормандия, който през 1066 г. побеждава при Хейстингс и става крал на Англия. Строи замъци като Лондонския Тауър и описва цялата страна в „Книгата на Страшния съд“. Умира през 1087 г. на 59 години.", "След него английският език се пълни с френски думи.", "При погребението тялото му не се побира в гроба и се пука."],
  "Фридрих Барбароса": ["Германски император от рода Хоенщауфен, наречен „Червената брада“. Воюва дълго в Италия и води Третия кръстоносен поход. Удавя се в река в Мала Азия през 1190 г. на 68 години.", "По пътя за Светите земи минава с армията си и през българските земи, край Пловдив.", "Легендата казва, че спи в планината Кифхойзер и ще се събуди, когато Германия има нужда от него."],
  "Авероес": ["Арабски философ, лекар и съдия от Кордоба в Андалусия. Пише подробни тълкувания на Аристотел, чрез които Европа отново го опознава. Изпада в немилост, но после е помилван; умира в Маракеш през 1198 г. на 72 години.", "В Европа го наричат просто „Тълкувателя“.", "Рафаело го рисува в „Атинската школа“ сред гръцките философи."],
  "Маймонид": ["Еврейски философ, лекар и законоучител, роден в Кордоба. Семейството му бяга от гонения, а той се установява в Кайро и става лекар на султан Саладин. Умира през 1204 г. на 66 години.", "Казват: „От Мойсей до Мойсей няма друг като Мойсей.“", "Пише и книги за здравословно хранене и за астмата."],
  "Фибоначи": ["Италиански математик от Пиза, израснал в Северна Африка. Чрез книгата си „Книга за сметането“ през 1202 г. въвежда в Европа арабските цифри и нулата. Умира около 1250 г. на около 80 години.", "Задачата му за размножаващи се зайци дава прочутите числа на Фибоначи: 1, 1, 2, 3, 5, 8…", "Тези числа се срещат в слънчогледа, шишарките и раковините."],
  "Цар Калоян": ["Български цар, брат на Асен и Петър. Получава корона от папата, а през 1205 г. при Одрин разбива рицарите на Четвъртия кръстоносен поход и пленява латинския император Балдуин. Убит е при обсадата на Солун през 1207 г. на 37 години.", "Сам се нарича „Ромеоубиец“ – отговор на прякора на Василий II.", "Гробът му вероятно е намерен в църквата „Св. 40 мъченици“ във Велико Търново."],
  "Валтер фон дер Фогелвайде": ["Най-известният немски миннезингер – поет и певец на любовта в Средновековието. Обикаля дворовете на князе и императори и пее за любов, политика и смисъла на живота. Умира около 1230 г. на около 60 години.", "Знаем за него само от една сметка – епископ му плаща за кожено палто.", "Според легендата завещава птиците на гроба му да се хранят с жито всеки ден."],
  "Цар Иван Асен II": ["Български цар, при когото Второто българско царство е най-голямо – на три морета. През 1230 г. разбива епирския владетел Теодор Комнин при Клокотница, но пуска пленниците си. Умира през 1241 г. на около 51 години.", "Пуска пленените войници да се приберат у дома – затова народът и враговете го уважават.", "Надпис в църквата „Св. 40 мъченици“ описва победата му."],
  "Албертус Магнус": ["Германски монах доминиканец, философ и естествоизпитател, учител на Тома Аквински. Изучава растения, животни, минерали и химия и пише за почти всичко. Умира в Кьолн през 1280 г. на около 80 години.", "Пръв описва чистия арсен.", "Наричат го „Доктор Универсалис“ – защото знае за всичко."],
  "Кублай хан": ["Монголски хан, внук на Чингис хан. Завладява цял Китай, основава династията Юан и прави Пекин своя столица. Опитва се на два пъти да нахлуе в Япония, но бури разбиват флота му. Умира през 1294 г. на 78 години.", "Марко Поло служи в двора му около 17 години.", "Японците наричат спасилите ги бури „камикадзе“ – „божествен вятър“."],
  "Майстер Екхарт": ["Германски монах доминиканец, богослов и мистик. Проповядва на немски, а не на латински, и учи, че Бог може да се роди в душата на всеки човек. Обвинен е в ерес и умира около 1328 г. на около 68 години, преди присъдата.", "Помага немският да стане език и за философия.", "Мястото и датата на смъртта му не са известни."],
  "Джото": ["Италиански художник и архитект от Флоренция. Рисува хора с истински чувства и обем, вместо плоските лица от иконите – начало на Ренесанса в изкуството. Проектира камбанарията на катедралата във Флоренция. Умира през 1337 г. на 70 години.", "Разказват, че като момче рисува овца на камък толкова добре, че художник го взима за ученик.", "Като доказателство за майсторството си рисува съвършен кръг с един замах."],
  "Манса Муса": ["Владетел на империята Мали в Западна Африка, богата на злато. Вероятно най-богатият човек в историята. Строи джамии и училища в Тимбукту. Умира около 1337 г. на около 57 години.", "По пътя за Мека раздава толкова злато в Кайро, че цената му пада за години.", "На европейски карти от 14 век е нарисуван със златна корона и златна топка в ръка."],
  "Ибн Батута": ["Мароканец, който тръгва на поклонение в Мека на 21 години и се прибира след 24 години. Изминава около 120 000 км – от Северна Африка до Китай, Индия и Източна Африка. Умира около 1369 г. на 65 години.", "Изминава три пъти повече от Марко Поло.", "Служи като съдия в Делхи и на Малдивите."],
  "Франческо Петрарка": ["Италиански поет и учен, „баща на хуманизма“. Пише сонети за любимата си Лаура, която вижда в църква и обича цял живот без отговор. Търси и преписва древни ръкописи. Умира през 1374 г. на 69 години.", "Той пръв нарича Средновековието „тъмни векове“.", "Изкачва връх Ванту само за да види гледката – нещо необичайно за времето си."],
  "Патриарх Евтимий": ["Последният патриарх на Търновското царство и голям книжовник. Прави правописна реформа и поправя църковните книги. През 1393 г. води защитата на Търново срещу османците. След падането на града е заточен и умира около 1402 г. на около 77 години.", "Според преданието, когато турците влизат, излиза пред тях без страх и те не го посичат.", "Учениците му разнасят Търновската книжовна школа до Сърбия и Русия."],
  "Тимур": ["Тюркско-монголски завоевател, наричан Тамерлан – „Куция Тимур“. Създава огромна империя от Индия до Мала Азия, а столицата му Самарканд е украсена с великолепни сгради. Умира през 1405 г. на 68 години, на път да нападне Китай.", "През 1402 г. разбива и пленява османския султан Баязид I – това отлага падането на Константинопол с 50 години.", "Учените, отворили гроба му през 1941 г., потвърждават, че е куцал."],
  "Джефри Чосър": ["Английски поет, „баща на английската литература“. Пише „Кентърбърийски разкази“ – истории на поклонници, разказани по пътя. Пише на английски, когато в двора се говори френски. Умира през 1400 г. на около 57 години.", "Работи като митнически чиновник и дипломат.", "Първият поет, погребан в „Ъгъла на поетите“ в Уестминстър."],
  "Цар Иван Шишман": ["Последният цар на Търновското царство. Опитва се да се съпротивлява на османците, но през 1393 г. Търново пада. Умира през 1395 г. на около 45 години – по предание в плен или в битка край Никопол.", "За него има много народни песни и легенди.", "Много места из България носят името му – „Шишманово кале“, „Шишманови порти“."],
  "Джън Хъ": ["Китайски адмирал и евнух. Води седем огромни морски експедиции до Индия, Арабия и Източна Африка с кораби, много по-големи от тези на Колумб. Умира около 1433 г. на около 62 години, вероятно в морето.", "Флотите му имат до 300 кораба и около 28 000 души.", "Донася жираф за императора от Африка."],
  "Ян Хус": ["Чешки свещеник и професор в Прага, който критикува богатството и греховете на църквата. Повикан е на събор в Констанц с обещание за безопасност, но е арестуван и изгорен на клада през 1415 г. на 43 години.", "Смъртта му предизвиква хуситските войни в Бохемия.", "Пише и проповядва на чешки и опростява чешкия правопис."],
  "Влад Цепеш": ["Влашки княз, който воюва срещу османците. Известен с жестокостта си – набива враговете си на колове. Убит е в битка през 1476 г. на 45 години.", "Името „Дракула“ идва от баща му, член на Ордена на дракона.", "Ирландецът Брам Стокър използва името му за вампира граф Дракула."],
  "Мехмед II Завоевателя": ["Османски султан, който на 21 години превзема Константинопол през 1453 г. и слага край на Византия. Прави града своя столица и строи двореца Топкапъ. Умира през 1481 г. на 49 години.", "Прекарва корабите си по суша, по намазани дъски, за да заобиколи веригата в Златния рог.", "Говори няколко езика и кани италиански художник да го нарисува."],
  "Лукас Кранах Старши": ["Германски художник от Ренесанса, придворен живописец в Саксония. Рисува портрети, сред тях най-известните на Мартин Лутер, с когото е приятел. Притежава и аптека и печатница. Умира през 1553 г. на 81 години.", "Кум е на сватбата на Лутер.", "Подписва картините си с крилата змия."],
  "Парацелз": ["Швейцарски лекар и алхимик. Отхвърля старите учения, пише на немски и използва химични вещества като лекарства. Обикаля Европа и се кара с колегите си. Умира в Залцбург през 1541 г. на 47 години.", "Казва: „Всичко е отрова – само дозата прави нещо да не е отрова.“", "Изгаря публично книгите на Авицена, за да покаже, че е време за нова медицина."],
  "Ханс Холбайн Младши": ["Германски художник от Аугсбург, един от най-големите портретисти. Работи в Базел, а после в Англия като придворен художник на Хенри VIII. Умира в Лондон през 1543 г. на 46 години, вероятно от чума.", "В картината „Посланиците“ има изкривен череп, който се вижда правилно само отстрани.", "По негов портрет Хенри VIII избира съпруга, но се разочарова, когато я вижда на живо."],
  "Карл V": ["Император на Свещената Римска империя и крал на Испания от рода Хабсбург. Владее толкова земи в Европа и Америка, че „слънцето никога не залязва“ над тях. Воюва с Франция, османците и протестантите. Абдикира и умира в манастир през 1558 г. на 58 години.", "Казва, че говори испански на Бог, италиански на жените, френски на мъжете и немски на коня си.", "Изправя Лутер пред събора във Вормс."],
  "Готфрид Вилхелм Лайбниц": ["Германски философ и математик от Лайпциг, един от последните „всезнайковци“. Измисля диференциалното смятане независимо от Нютон и строи механичен калкулатор. Умира в Хановер през 1716 г. на 70 години, почти забравен.", "Описва двоичната система от 0 и 1, на която работят днешните компютри.", "На погребението му идва само секретарят му."],
  "Мария Сибила Мериан": ["Германска художничка и естествоизпитателка от Франкфурт. Рисува насекоми и растения и показва как гъсеницата става пеперуда. На 52 години пътува със дъщеря си до Суринам, за да изучава тропическите насекоми. Умира в Амстердам през 1717 г. на 69 години.", "По онова време много хора вярват, че насекомите се раждат от калта.", "Портретът ѝ е бил на немската банкнота от 500 марки."],
  "Барон Мюнхаузен": ["Германски благородник, служил като офицер в руската армия срещу турците. Връща се в имението си край Хановер и разказва на гостите невероятни истории за приключенията си. Умира през 1797 г. на 76 години.", "В разказите лети на гюле и се издърпва от блатото за собствената си коса.", "Други издават историите му без неговото съгласие и той се сърди."],
  "Готхолд Ефраим Лесинг": ["Германски писател и драматург на Просвещението. В пиесата „Натан Мъдрия“ призовава към търпимост между християни, евреи и мюсюлмани. Работи като библиотекар във Волфенбютел. Умира през 1781 г. на 52 години.", "В „Натан Мъдрия“ е прочутата притча за трите пръстена.", "Един от първите германци, които се опитват да живеят само от писане."],
  "Йозеф Хайдн": ["Австрийски композитор, „баща на симфонията и струнния квартет“. Близо 30 години е придворен музикант на князете Естерхази. Пише над 100 симфонии и е учител на Бетовен. Умира във Виена през 1809 г. на 77 години.", "Мелодията му за императора днес е химнът на Германия.", "В симфонията „Сбогуване“ музикантите един по един гасят свещите и излизат – намек към княза, че искат отпуск."],
  "Софроний Врачански": ["Български духовник и книжовник, роден като Стойко Владиславов в Котел. Преписва „История славянобългарска“ на Паисий и става епископ на Враца. Пише „Неделник“ – първата печатна книга на новобългарски език (1806). Умира в Букурещ през 1813 г. на 74 години.", "Пише и „Житие и страдания грешнаго Софрония“ – първата българска автобиография.", "Помага на руската армия и пише призиви към българите."],
  "Каролайн Хершел": ["Германска астрономка от Хановер, сестра на Уилям Хершел. Отива при брат си в Англия като певица, но става негова помощничка и сама открива осем комети. Връща се в Хановер и умира през 1848 г. на 97 години.", "Първата жена, на която кралят плаща заплата за научна работа.", "Като дете боледува от тиф и остава висока само 1,30 м."],
  "Георг Вилхелм Фридрих Хегел": ["Германски философ от Щутгарт. Учи, че историята се движи напред чрез противоречия, а светът е развитие на духа. Преподава в Берлин и е най-влиятелният философ на времето си. Умира от холера през 1831 г. на 61 години.", "Пише книгата си „Феноменология на духа“, докато Наполеон влиза в Йена.", "Приятел е от студентските години с поета Хьолдерлин."],
  "Фридрих Хьолдерлин": ["Германски поет от Швабия, който пише възторжени стихове за Древна Гърция и природата. На около 36 години се разболява психически и прекарва последните 36 години от живота си в една кула в Тюбинген, при семейството на дърводелец. Умира през 1843 г. на 73 години.", "Кулата на Хьолдерлин в Тюбинген е днес музей.", "Подписва късните си стихове с измислени имена като „Скарданели“."],
  "Каспар Давид Фридрих": ["Германски художник на романтизма от Грайфсвалд. Рисува самотни фигури пред мъгли, морета и планини. В края на живота си е забравен и беден. Умира в Дрезден през 1840 г. на 65 години.", "Най-известната му картина е „Странникът над морето от мъгла“.", "Като момче брат му се удавя, докато го спасява при пързаляне на лед."],
  "Карл Дрез": ["Германски изобретател от Карлсруе. През 1817 г. прави „машината за бягане“ – дървено колело без педали, предшественик на велосипеда. Изобретява и пишеща машина. Умира беден през 1851 г. на 66 години.", "Измисля колелото, след като годината без лято убива много коне – нужен е транспорт без тях.", "Изобретява и механична машина за записване на пиано музика."],
  "Вилхелм Грим": ["Германски езиковед и събирач на приказки, по-малкият от братя Грим. Заедно с брат си Якоб събира „Детски и домашни приказки“ – „Снежанка“, „Пепеляшка“, „Хензел и Гретел“. Започват и огромния Немски речник. Умира в Берлин през 1859 г. на 73 години.", "Вилхелм е този, който преразказва приказките по-меко и красиво за децата.", "Речникът, започнат от братята, е завършен чак през 1961 г."],
  "Артур Шопенхауер": ["Германски философ от Данциг, известен с песимизма си. Учи, че светът се движи от сляпа воля, а животът е страдание, което изкуството и състраданието облекчават. Признание получава едва на стари години. Умира във Франкфурт през 1860 г. на 72 години.", "Нарочно пуска лекциите си по едно и също време с Хегел – и при него не идва почти никой.", "Живее с поредица пудели, всичките наречени Атма."],
  "Васил Априлов": ["Български търговец и дарител от Габрово, живял в Одеса. През 1835 г. заедно с Никола Палаузов основава в Габрово първото светско българско училище. Умира в Галац през 1847 г. на 58 години.", "Като младеж смята себе си за грък – Юрий Венелин го „обръща“ към българщината.", "Габровската Априловска гимназия носи името му."],
  "Неофит Рилски": ["Български монах, учител и книжовник от Банско, „патриархът на българската педагогика“. Пише първата българска граматика (1835) и става първият учител в Априловското училище в Габрово. Прекарва последните си години в Рилския манастир, където умира през 1881 г. на 88 години.", "Работи 30 години над голям речник на българския език.", "Превежда Новия завет на говорим български."],
  "Хайнрих Хайне": ["Германски поет от Дюселдорф с еврейски корени. Пише нежни любовни стихове, но и остра сатира. Заради цензурата живее в Париж, където прекарва последните осем години прикован на легло. Умира през 1856 г. на 58 години.", "Стихотворението му „Лорелай“ става народна песен.", "Пише пророчески: „Там, където горят книги, накрая горят и хора.“"],
  "Петър Берон": ["Български учен и просветител от Котел. През 1824 г. издава „Буквар с различни поучения“ – „Рибния буквар“, първия светски български учебник. По-късно става лекар и пише трудове по физика и философия. Убит е в Крайова през 1871 г. на 72 години.", "Букварът се нарича „Рибен“ заради делфина на последната страница.", "Завещава богатството си на българските училища."],
  "Кольо Фичето": ["Български възрожденски строител от Дряново, самоук майстор. Строи мостове, църкви и сгради – мостът в Бяла, покритият мост в Ловеч, конака в Търново. Умира през 1881 г. на 81 години.", "Прякорът „Фичето“ значи „малкият“ – той е дребен на ръст.", "Мостът му в Бяла е дълъг 276 метра."],
  "Захари Зограф": ["Български възрожденски иконописец от Самоков. Изписва стенописи в Рилския, Бачковския и Троянския манастир. Рисува и обикновени хора и себе си, което е новост. Умира от тиф през 1853 г. на 43 години.", "Рисува първия български автопортрет.", "В Троянския манастир рисува Страшния съд с хора в тогавашни дрехи."],
  "Роберт Шуман": ["Германски композитор на романтизма от Цвикау. Иска да стане пианист, но наранява ръката си и се отдава на композирането. Жени се за пианистката Клара Вик. Страда от тежка депресия, хвърля се в Рейн и умира в лечебница през 1856 г. на 46 години.", "Пише над сто песни в една-единствена година – годината на сватбата си.", "Открива и подкрепя младия Брамс."],
  "Баба Тонка": ["Тонка Обретенова от Русе, „майката на революционерите“. Домът ѝ е тайна квартира на комитетите – там се крият бунтовници и оръжие. Синовете ѝ участват в борбата, двама от тях загиват. Умира през 1893 г. на 81 години.", "Носи оръжие и писма, скрити под дрехите си, покрай турската стража.", "И дъщеря ѝ Петрана е революционерка."],
  "Вернер фон Сименс": ["Германски изобретател и предприемач. Основава фирмата „Сименс“, строи телеграфни линии през цели континенти и открива как да прави мощни електрически генератори. Умира през 1892 г. на 75 години.", "Прави първия електрически трамвай и първия електрически асансьор.", "Мерната единица за електрическа проводимост се казва „сименс“."],
  "Евлоги Георгиев": ["Български търговец и банкер от Карлово, живял в Букурещ, заедно с брат си Христо Георгиев. Дарява огромна сума и земя за създаването на Софийския университет. Умира в Букурещ през 1897 г. на 78 години.", "Ректоратът на Софийския университет е построен на мястото, дарено от братята, и на фасадата му са техните статуи.", "Дава пари и на революционерите, но е против въоръжено въстание."],
  "Клара Шуман": ["Германска пианистка и композиторка от Лайпциг, чудо-дете. Омъжва се за Роберт Шуман против волята на баща си, ражда осем деца и продължава да концертира из Европа. Умира през 1896 г. на 76 години.", "Близки приятели е с Брамс цял живот.", "Портретът ѝ е бил на немската банкнота от 100 марки."],
  "Теодор Фонтане": ["Германски писател от Нойрупин, аптекар по професия. Работи като журналист и военен кореспондент и пише за пътуванията си из Бранденбург. Най-известните си романи, като „Ефи Брийст“, пише след 60 години. Умира в Берлин през 1898 г. на 78 години.", "Като кореспондент през 1870 г. е арестуван от французите като шпионин.", "Баладата му за господин фон Рибек и крушите се учи в немските училища."],
  "Добри Чинтулов": ["Български поет и учител от Сливен. Пише бунтовни стихове, които стават песни, пети от целия народ. Преподава в Сливен и умира там през 1886 г. на 64 години.", "Песента му „Стани, стани, юнак балкански“ е пята от революционерите.", "Стиховете му се разпространяват устно, без да са печатани."],
  "Хайнрих Шлиман": ["Германски търговец и археолог. Забогатява от търговия и златната треска, а после търси Троя по стиховете на Омир и я открива в Турция. Разкопава и Микена. Умира в Неапол през 1890 г. на 68 години.", "Изнася тайно „съкровището на Приам“ и слага скъпоценностите на жена си.", "Говори над десет езика, като учи всеки за няколко седмици."],
  "Найден Геров": ["Български възрожденец, учител и езиковед от Копривщица. Създава „Речник на българския език“ – огромен труд с над 70 000 думи. Дълги години е руски консул в Пловдив. Умира през 1900 г. на 77 години.", "Още като ученик пише първата българска поема.", "Като консул помага на много българи да избягат от преследване."],
  "Йохан Щраус (син)": ["Австрийски композитор, „кралят на валса“. Пише над 500 валса, полки и оперети, сред тях „На хубавия син Дунав“ и „Прилепът“. Свири с оркестъра си из цяла Европа и Америка. Умира във Виена през 1899 г. на 73 години.", "Баща му, също композитор, не иска синът му да става музикант.", "„На хубавия син Дунав“ звучи всяка Нова година във Виена."],
  "Петко Славейков": ["Български поет, журналист и политик от Търново. Издава вестници, събира хиляди народни песни и пословици и се бори за самостоятелна българска църква. След Освобождението е министър. Умира през 1895 г. на 67 години.", "Баща е на поета Пенчо Славейков.", "Издава вестниците „Гайда“ и „Македония“."],
  "Йохана Шпири": ["Швейцарска писателка от село край Цюрих. Пише „Хайди“ – историята на момиче, което живее при дядо си в Алпите. Умира в Цюрих през 1901 г. на 74 години.", "„Хайди“ е преведена на около 50 езика.", "Първата ѝ книга излиза без името ѝ – само с инициали."],
  "Панайот Хитов": ["Български хайдутин и войвода от Сливен. Води чети в Балкана и през 1867 г. превежда през Стара планина четата, в която е и Васил Левски като знаменосец. Доживява Освобождението и умира в Русе през 1918 г. на 87 години.", "Пише спомени „Как станах хайдутин“.", "Левски е негов знаменосец."],
  "Филип Тотю": ["Български хайдутин и войвода от село Гърци (днес Вишовград). През 1867 г. води чета от Румъния в Балкана заедно с Панайот Хитов. Доживява Освобождението и умира през 1907 г. на 77 години.", "За него се пеят народни песни.", "Той е сред малкото войводи, доживели Освобождението."],
  "Франц Йосиф I": ["Император на Австрия и крал на Унгария, който управлява 68 години – от 1848 до 1916 г. Преживява загуба на войни, смъртта на сина си и убийството на жена си Сиси. След убийството на престолонаследника му обявява война на Сърбия – начало на Първата световна война. Умира през 1916 г. на 86 години.", "Става император на 18 години.", "Спи на желязно военно легло и става всеки ден в 4 сутринта."],
  "Николаус Ото": ["Германски изобретател, който се самоучи. През 1876 г. създава четиритактовия бензинов двигател с вътрешно горене, който задвижва повечето коли. Умира в Кьолн през 1891 г. на 58 години.", "Преди това е пътуващ търговец на захар и колониални стоки.", "Четиритактовият цикъл и днес се нарича „цикъл на Ото“."],
  "Вилхелм Буш": ["Германски поет и художник, баща на комикса. Създава „Макс и Мориц“ – историята в рисунки и стихове за двама палави момчета. Живее тихо на село и умира през 1908 г. на 75 години.", "Продава правата за „Макс и Мориц“ за малка сума, а издателят забогатява.", "Като дете живее при чичо си пастор, а родителите си не вижда три години."],
  "Йоханес Брамс": ["Германски композитор от Хамбург. Като момче свири на пиано в кръчмите на пристанището. По-късно се установява във Виена и пише симфонии, концерти и „Унгарски танци“. Умира през 1897 г. на 63 години.", "„Приспивната песен“ на Брамс е една от най-известните мелодии на света.", "Пише първата си симфония цели 21 години – страхува се от сянката на Бетовен."],
  "Любен Каравелов": ["Български писател, журналист и революционер от Копривщица. В Букурещ издава вестници и е пръв председател на Българския революционен централен комитет. Умира в Русе от туберкулоза през 1879 г. на 44 години, малко след Освобождението.", "Пише повестта „Българи от старо време“.", "При пожар в Русе по време на войната губи библиотеката и архива си."],
  "Готлиб Даймлер": ["Германски инженер и изобретател от Шорндорф. Заедно с Вилхелм Майбах създава лек и бърз бензинов двигател, първия мотоциклет и една от първите коли. Основава фирма, от която по-късно излиза „Мерцедес-Бенц“. Умира през 1900 г. на 65 години.", "Първият мотоциклет е дървен и е наречен „Райтваген“.", "Тричленната звезда на „Мерцедес“ означава двигатели за суша, вода и въздух."],
  "Императрица Сиси": ["Елизабет Баварска, съпруга на император Франц Йосиф. Известна с красотата си и с дългата си коса, тя ненавижда дворцовия живот и постоянно пътува. Обича Унгария и помага за Австро-Унгария. Убита е с пила от анархист в Женева през 1898 г. на 60 години.", "Косата ѝ стига до петите и миенето ѝ отнема цял ден.", "Пробождането е толкова тънко, че тя продължава да върви, без да разбере, че е ранена."],
  "Фердинанд фон Цепелин": ["Германски граф и генерал от Констанц. След пенсионирането си на 52 години се захваща да строи огромни дирижабли с твърд скелет. Първият му цепелин полита през 1900 г. над Боденското езеро. Умира през 1917 г. на 78 години.", "Като наблюдател в Гражданската война в САЩ за първи път се качва на балон.", "Цепелините превозват пътници през Атлантика години преди самолетите."],
  "Хаджи Димитър": ["Български хайдутин и революционер от Сливен. През 1868 г. заедно със Стефан Караджа минава Дунава с чета от 127 души. След тежки боеве загива на връх Бузлуджа на 28 години.", "Ботев го безсмъртява в стихотворението „Хаджи Димитър“: „Тоз, който падне в бой за свобода, той не умира…“", "Къщата му в Сливен днес е музей."],
  "Карл Май": ["Германски писател от Саксония, автор на приключения за Дивия Запад и Ориента – с героите Винету и Old Shatterhand. Като млад е в затвора за измами. Умира през 1912 г. на 70 години.", "Пише за Америка, без да е бил там – посещава я едва на стари години.", "Книгите му са продадени в над 200 милиона копия."],
  "Георги Бенковски": ["Български революционер от Копривщица, роден като Гаврил Хлътев. Ръководител на Панагюрския революционен окръг през Априлското въстание 1876 г. и водач на „Хвърковатата чета“. Убит е в засада край Тетевен на 33 години.", "Ушива си униформа и обикаля селата на кон, за да вдигне народа.", "Името „Бенковски“ взима от поляк, когото среща в Мала Азия."],
  "Капитан Петко войвода": ["Български хайдутин и революционер от Доганхисар (днес Аисими, Гърция). Десетилетия воюва срещу османците в Родопите и Беломорието. След Освобождението живее във Варна и умира през 1900 г. на 55 години.", "Сражава се в Италия заедно с Гарибалди.", "За него е сниман популярният сериал „Капитан Петко войвода“."],
  "Лудвиг II Баварски": ["Крал на Бавария, наричан „Приказния крал“. Вместо с политика се занимава с музиката на Вагнер и строи приказни замъци като Нойшванщайн. Обявен е за луд и свален, а ден по-късно е намерен мъртъв в езерото Щарнберг на 40 години.", "Нойшванщайн вдъхновява замъка на Спящата красавица на „Дисни“.", "Смъртта му и до днес е загадка."],
  "Ото Лилиентал": ["Германски инженер, „кралят на планера“. Изучава полета на щъркелите и прави над 2000 полета с планери, които сам конструира. При падане през 1896 г. си чупи гръбнака и умира на 48 години.", "Последните му думи са: „Трябва да има жертви.“", "Братя Райт изучават неговите полети."],
  "Захари Стоянов": ["Български революционер и писател от Медвен, бивш овчар. Участва в Априлското въстание и описва преживяното в „Записки по българските въстания“. Води Съединението през 1885 г. и е председател на Народното събрание. Умира в Париж през 1889 г. на 39 години.", "Пише биографии на Левски, Ботев и Бенковски.", "Започва като овчарче и се учи сам."],
  "Тодор Каблешков": ["Български революционер от Копривщица. На 20 април 1876 г. пише „кървавото писмо“, с което обявява Априлското въстание. След разгрома е заловен и се застрелва в плен в Габрово на 25 години.", "Наречено е „кърваво“, защото по предание е подпечатано с кръвта на убит полицай.", "Говори няколко езика и учи в Цариград."],
  "Стефан Стамболов": ["Български революционер и държавник от Търново. След Освобождението е председател на Народното събрание и регент, а после министър-председател. Управлява твърдо, но модернизира страната. Нападнат е с ножове в София и умира през 1895 г. на 41 години.", "Наричат го „българския Бизмарк“.", "Като млад пише стихове и е приятел на Ботев."],
  "Райна Княгиня": ["Райна Попгеоргиева, учителка от Панагюрище. Ушива знамето на Априлското въстание с надпис „Свобода или смърт“. След въстанието е хвърлена в затвора и измъчвана. По-късно става акушерка и умира през 1917 г. на 61 години.", "Прякора „Княгиня“ получава от Бенковски."],
  "Княз Александър Батенберг": ["Германски принц, избран за първия княз на свободна България през 1879 г. на 22 години. Подкрепя Съединението и води армията към победата при Сливница през 1885 г. Свален е с преврат и умира в Грац през 1893 г. на 36 години.", "Погребан е по негово желание в София – мавзолеят му е в центъра на града.", "Тайно е сгоден за внучката на кралица Виктория, но бракът не се случва."],
  "Хайнрих Херц": ["Германски физик от Хамбург. През 1887 г. пръв доказва, че съществуват електромагнитни вълни – основа на радиото, телевизията и мобилните телефони. Умира през 1894 г. на 36 години.", "Казва, че откритието му „няма никакво практическо приложение“.", "Единицата за честота се казва „херц“."],
  "Рудолф Дизел": ["Германски инженер, роден в Париж. Изобретява двигателя, който запалва горивото само чрез сгъстяване на въздуха – дизеловия двигател. През 1913 г. изчезва от кораб в Ламанша и е намерен мъртъв на 55 години.", "Първият му двигател работи с фъстъчено масло на изложението в Париж.", "Смъртта му и до днес е загадка – инцидент, самоубийство или убийство."],
  "Густав Малер": ["Австрийски композитор и диригент от Бохемия. Ръководи Виенската опера и пише огромни симфонии, в които звучат природа, смърт и надежда. Умира във Виена през 1911 г. на 50 години.", "Казва: „Симфонията трябва да е като света – да побира всичко.“", "Страхува се да напише девета симфония, защото Бетовен и други умират след деветата."],
  "Цар Фердинанд": ["Германски принц от рода Сакс-Кобург-Гота, избран за княз на България през 1887 г. През 1908 г. обявява независимостта и става цар. Въвлича страната в Балканските и Първата световна война. Абдикира през 1918 г. и умира в Кобург през 1948 г. на 87 години.", "Страстен ботаник и ентомолог – създава градини и музеи.", "Обича сам да кара влак."],
  "Петър Дънов": ["Български духовен учител, наричан Учителя Беинса Дуно. Основава Бялото братство и учи на любов, мъдрост и истина. Последователите му играят паневритмия и посрещат изгрева на Рила. Умира в София през 1944 г. на 80 години.", "Всяко лято води последователите си на Седемте рилски езера.", "Пише и музика за паневритмията."],
  "Пенчо Славейков": ["Български поет от Трявна, син на Петко Славейков. Учи в Лайпциг и иска да издигне българската поезия до европейската. Пише епоса „Кървава песен“. Номиниран е за Нобелова награда, но умира в Италия през 1912 г. на 46 години.", "Като момче замръзва в ледена вода и остава с трудности при ходене и говорене цял живот.", "В антологията „На острова на блажените“ представя измислени поети – а стиховете са негови."],
  "Гоце Делчев": ["Български революционер и учител от Кукуш. Водач на Вътрешната македоно-одринска революционна организация (ВМОРО), която се бори за освобождение на Македония и Одринско. Загива в сражение край село Баница през 1903 г. на 31 години.", "Казва: „Разбирам света единствено като поле за културно съревнование между народите.“", "Учи във Военното училище в София, но е изключен."],
  "Яне Сандански": ["Български революционер от Влахи, наричан „Пиринския цар“. Войвода на ВМОРО, който води чети в Пирин. Организира отвличането на американската мисионерка Мис Стоун за откуп. Убит е в засада край Рожен през 1915 г. на 42 години.", "Откупът за Мис Стоун е 14 000 турски лири, събрани в Америка.", "Град Сандански носи неговото име."],
  "Фердинанд Порше": ["Австрийски автомобилен конструктор от Бохемия. Прави една от първите хибридни коли още през 1900 г., а през 30-те години конструира „Фолксваген Костенурка“. Основава фирмата „Порше“ и умира през 1951 г. на 75 години.", "„Костенурката“ е произведена в над 21 милиона броя.", "Никога не завършва университет, но получава почетна докторска титла."],
  "Райнер Мария Рилке": ["Австрийски поет, роден в Прага. Пише „Дуинските елегии“ и „Сонети към Орфей“, а „Писма до един млад поет“ се четат и до днес. Умира от левкемия в Швейцария през 1926 г. на 51 години.", "Като малък майка му го облича като момиче.", "Работи като секретар на скулптора Роден в Париж."],
  "Конрад Аденауер": ["Германски политик, кмет на Кьолн, свален от нацистите. След войната на 73 години става първият канцлер на Западна Германия и я води 14 години – към демокрация, икономическо чудо и помирение с Франция. Умира през 1967 г. на 91 години.", "Става канцлер с мнозинство от един глас – своя собствен.", "Патентова колбас от соя и уред против насекоми."],
  "Херман Хесе": ["Германски писател от Шварцвалд, по-късно швейцарски гражданин. В романи като „Степният вълк“, „Сидхарта“ и „Играта на стъклени перли“ търси пътя на човека към себе си. Получава Нобелова награда през 1946 г. и умира през 1962 г. на 85 години.", "Като момче бяга от манастирско училище.", "През 60-те години става любимец на хипитата."],
  "Стамен Григоров": ["Български лекар и микробиолог от село Студен извор. През 1905 г. в Женева открива бактерията, от която става българското кисело мляко – Lactobacillus bulgaricus. По-късно прави и ваксина срещу туберкулоза. Умира през 1945 г. на 67 години.", "Открива я на 27 години, още като студент.", "В Студен извор има музей на киселото мляко."],
  "Лизе Майтнер": ["Австрийска физичка от Виена. Работи 30 години в Берлин с Ото Хан. Като еврейка бяга от нацистите в Швеция, откъдето обяснява ядреното делене. Отказва да работи по атомната бомба. Умира в Англия през 1968 г. на 89 години.", "Нобеловата награда за деленето получава само Хан, а тя е подмината.", "Химичният елемент майтнерий носи нейното име."],
  "Александър Стамболийски": ["Български политик от Славовица, водач на Земеделския съюз. Противник на войната, той е хвърлен в затвора, а след нея става министър-председател. Прави поземлена реформа и въвежда трудова повинност. Свален е с преврат и е убит жестоко през 1923 г. на 44 години.", "Убийците му отрязват ръката, с която е подписал договора с Югославия."],
  "Ото Хан": ["Германски химик от Франкфурт, „баща на ядрената химия“. През 1938 г. с Фриц Щрасман открива деленето на урановото ядро. Получава Нобелова награда за химия. След войната се бори срещу ядрените оръжия. Умира през 1968 г. на 89 години.", "Като научава за Хирошима, е толкова разстроен, че колегите му се боят за него.", "Научава за Нобеловата си награда в британски плен."],
  "Йордан Йовков": ["Български писател от Жеравна, майстор на разказа. Учител в Добруджа, а после дипломат в Букурещ. Пише „Старопланински легенди“, „Последна радост“ и „Чифликът край границата“. Умира в Пловдив през 1937 г. на 56 години.", "Разказът „Песента на колелетата“ се учи в училище.", "Воюва като офицер в Балканските и Първата световна война."],
  "Алфред Вегенер": ["Германски метеоролог и полярен изследовател от Берлин. Предлага, че континентите някога са били един – Пангея – и бавно се раздалечават. Никой не му вярва приживе. Умира в Гренландия през 1930 г. на 50 години, по време на експедиция.", "Забелязва, че брегът на Южна Америка пасва на Африка като парче пъзел.", "Поставя световен рекорд за най-дълъг полет с балон – над 52 часа."],
  "Стефан Цвайг": ["Австрийски писател от Виена, един от най-четените в света през 30-те години. Пише новели, биографии и спомените „Вчерашният свят“. Като евреин бяга от нацистите в Англия и после в Бразилия, където отнема живота си през 1942 г. на 60 години.", "Последната му новела е „Шахматна новела“.", "Нацистите горят книгите му."],
  "Владимир Димитров – Майстора": ["Български художник от Фролош, Кюстендилско. Рисува селяни, моми и плодове в ярки, приказни цветове. Живее скромно на село в Шишковци. Умира през 1960 г. на 78 години.", "Подарява картините си на селяните, които го хранят.", "Наречен е „Майстора“ още от младостта си."],
  "Асен Златаров": ["Български химик, лекар и общественик от Хасково. Изследва химията на храните и пише научно-популярни книги. Организира безплатни лекции и помощ за бедните. Умира през 1936 г. на 51 години.", "Пише и стихове.", "Университетът в Бургас носи неговото име."],
  "Ран Босилек": ["Генчо Негенцов, български детски писател от Габрово. Пише „Патиланци“ и „Неродена мома“, превежда и преразказва приказки. Умира през 1958 г. на 71 години.", "Псевдонимът му означава „ранен босилек“.", "Героите от „Патиланско царство“ – Рижко, Гого и Сачко – знае всяко българско дете."],
  "Дора Габе": ["Българска поетеса от Дъбовик, Добричко. Пише стихове за деца и за възрастни и превежда от много езици. Живее почти цял век и умира през 1983 г. на 97 години.", "Учи в Женева и Гренобъл и говори няколко езика.", "Поколения деца знаят стиховете ѝ наизуст."],
  "Димчо Дебелянов": ["Български поет от Копривщица. Пише нежни и тъжни стихове, като „Да се завърнеш в бащината къща“. Записва се доброволец в Първата световна война и загива край Горно Караджово през 1916 г. на 29 години.", "Стихотворението „Аз искам да те помня все така“ е едно от най-обичаните в България.", "Паметникът на гроба му в Копривщица – майка, чакаща сина си – е известен в цялата страна."],
  "Ервин Шрьодингер": ["Австрийски физик от Виена, един от създателите на квантовата механика. Неговото уравнение описва поведението на електроните. Получава Нобелова награда през 1933 г. Умира във Виена през 1961 г. на 73 години.", "Измисля мисловния опит с котката, която е едновременно жива и мъртва, докато не отвориш кутията.", "Ликът му е бил на австрийската банкнота от 1000 шилинга."],
  "Чудомир": ["Димитър Чорбаджийски, български писател-хуморист и художник от Турия. Учител в Казанлък, пише смешни и топли разкази за селския живот. Умира през 1967 г. на 76 години.", "Подписва се само с „Чудомир“.", "Къщата му в Казанлък е музей и там се провежда празник на хумора."],
  "Дан Колов": ["Български борец от Сенник, Севлиевско, световен шампион по свободна борба. Заминава на 17 години за Америка, работи като дървосекач и миньор, после става звезда на ринга. Губи само няколко от над 1500 мача. Умира в родното си село през 1940 г. на 47 години.", "Казва: „Българин не може да бъде победен!“", "По предание удържа с ръце два автомобила, които теглят в противоположни посоки."],
  "Цар Борис III": ["Цар на България от 1918 до 1943 г., син на Фердинанд. Управлява в трудни години и през Втората световна война е съюзник на Германия, но не праща войски на Източния фронт. Умира внезапно след среща с Хитлер през 1943 г. на 49 години.", "Обича влаковете и сам кара локомотиви, като баща си.", "При неговото управление българските евреи са спасени от депортиране."],
  "Димитър Пешев": ["Български политик от Кюстендил, заместник-председател на Народното събрание. През 1943 г. научава за готвеното депортиране на българските евреи и го спира, като събира подписи на депутати. Свален е от поста си, а после е съден от комунистите. Умира в бедност през 1973 г. на 78 години.", "Израел го обявява за „Праведник на света“.", "Действията му спасяват около 48 000 души."],
  "Гео Милев": ["Български поет от Раднево, авангардист. Ранен в Първата световна война, губи дясното си око. Поемата му „Септември“ описва потушеното въстание от 1923 г. и е забранена. През 1925 г. е отведен в полицията и изчезва; убит е на 30 години.", "Останките му са открити чак през 1954 г. в общ гроб.", "Учи в Лайпциг и превежда европейски поети."],
  "Георги Наджаков": ["Български физик от Дупница. През 1937 г. открива фотоелектретите – основа на по-късните ксерокси и лазерни принтери. Професор в Софийския университет. Умира през 1981 г. на 84 години.", "Работи при Пол Ланжвен в Париж.", "Без неговото откритие копирните машини може би щяха да се появят много по-късно."],
  "Иван Странски": ["Български физикохимик от София, основател на науката за растежа на кристалите. Работи в София и Берлин, където е и ректор на Техническия университет. Умира в Берлин през 1979 г. на 82 години.", "Механизмът на растеж „Странски–Кръстанов“ се използва и днес при направата на чипове."],
  "Иван Милев": ["Български художник от Казанлък. За кратък живот създава приказни картини с мотиви от фолклора, легендите и сецесиона. Умира от испански грип през 1927 г. на 30 години.", "Ликът му е на банкнотата от 5 лева.", "Рисува и декори за театъра."],
  "Христо Смирненски": ["Български поет от Кукуш. Пише за бедните и потиснатите, както и хумористични стихове. Умира от туберкулоза през 1923 г. на 24 години.", "Стихотворението „Приказка за стълбата“ се учи във всяко училище.", "Като малък губи два пръста при игра с експлозив."],
  "Димитър Талев": ["Български писател от Прилеп. Пише романа „Железният светилник“ и продълженията му за живота в Македония през Възраждането. Пратен е в лагер от комунистите. Умира през 1966 г. на 68 години.", "„Железният светилник“ е сред най-обичаните български романи.", "Номиниран е за Нобелова награда."],
  "Бертолт Брехт": ["Германски драматург и поет от Аугсбург. Пише „Опера за три гроша“ и „Майка Кураж“ и създава „епичния театър“, който кара зрителя да мисли, а не само да чувства. Бяга от нацистите и после основава театъра „Берлинер ансамбъл“. Умира през 1956 г. на 58 години.", "Песента „Мак Ножа“ от неговата опера става световен хит.", "В Америка е разпитван за комунистически възгледи и на другия ден заминава."],
  "Ерих Мария Ремарк": ["Германски писател от Оснабрюк. На 18 години е ранен в Първата световна война, а през 1929 г. пише „На Западния фронт нищо ново“ – един от най-известните романи против войната. Нацистите горят книгите му и той емигрира. Умира в Швейцария през 1970 г. на 72 години.", "Сестра му е екзекутирана от нацистите, отчасти заради него.", "Женен е за холивудската актриса Полет Годар."],
  "Панчо Владигеров": ["Български композитор и пианист, роден в Цюрих. Учи и работи в Берлин, после се връща в София и преподава в Музикалната академия. Пише „Българска рапсодия Вардар“. Умира през 1978 г. на 79 години.", "Има брат близнак – Любен, цигулар.", "Музикалната академия в София носи неговото име."],
  "Ерих Кестнер": ["Германски писател от Дрезден. Пише детските книги „Емил и детективите“, „Двойната Лоте“ и „Летящата класна стая“. Нацистите горят книгите му, а той гледа отстрани. Умира в Мюнхен през 1974 г. на 75 години.", "Единственият автор, който сам вижда как горят книгите му през 1933 г.", "По „Двойната Лоте“ е сниман филмът „Капан за родители“."],
  "Илия Бешков": ["Български художник и карикатурист от Плевен. С карикатурите си осмива властта и войната. Преподава в Художествената академия. Умира през 1958 г. на 57 години.", "Пише и разкази и спомени."],
  "Вернер Хайзенберг": ["Германски физик от Вюрцбург, един от създателите на квантовата механика. Открива „принципа на неопределеността“ – не може едновременно да се знаят точно положението и скоростта на частица. Получава Нобелова награда на 31 години. Умира през 1976 г. на 74 години.", "През войната ръководи германската атомна програма, която не стига до бомба.", "Измисля важна част от теорията си на остров Хелголанд, където е заради сенна хрема."],
  "Ангел Каралийчев": ["Български писател от Стражица, автор на приказки и разкази за деца. Пише „Ръжено зърно“ и „Житената питка“. Умира през 1972 г. на 69 години.", "Приказките му са преведени на десетки езици.", "Много от приказките му са по народни мотиви."],
  "Хайнц Рюман": ["Германски актьор от Есен, един от най-обичаните в историята на немското кино. Играе в над 100 филма – комедии като „Die Feuerzangenbowle“ и сериозни роли. Умира през 1994 г. на 92 години.", "Страстен пилот – лети със самолет до дълбока старост.", "На 91 години се снима при Вим Вендерс."],
  "Джон Атанасов": ["Американски физик и изобретател с баща българин от Бойчиновци. През 1939–1942 г. с Клифърд Бери създава първия електронен цифров компютър. Умира през 1995 г. на 91 години.", "Идеята му хрумва в крайпътна кръчма, след като кара 300 км през нощта.", "Съд в САЩ признава през 1973 г., че той е изобретил електронния компютър."],
  "Златю Бояджиев": ["Български художник от Брезово. Рисува селски сцени, празници и пловдивски улици. След инсулт на 48 години се научава да рисува с лявата ръка и създава приказни, гъсто населени картини. Умира през 1976 г. на 72 години.", "Картините му след инсулта са пълни със стотици малки фигури.", "Къщата-музей на Златю Бояджиев е в Стария град на Пловдив."],
  "Филип Кутев": ["Български композитор и диригент от Айтос. Основава Държавния ансамбъл за народни песни и танци, който прави българския фолклор известен по света. Умира през 1982 г. на 79 години.", "Ансамбълът му е първият професионален фолклорен ансамбъл в България (1951).", "Жена му Мария Кутева работи с него и продължава делото му."],
  "Макс Шмелинг": ["Германски боксьор от Бранденбург, световен шампион в тежка категория. През 1936 г. нокаутира непобедения американец Джо Луис. По-късно става бизнесмен и приятел на Луис. Умира през 2005 г. на 99 години.", "През 1938 г. крие две еврейски момчета в хотелската си стая и ги спасява.", "Плаща погребението на Джо Луис."],
  "Хана Арент": ["Германско-американска философка от еврейско семейство в Хановер. Бяга от нацистите във Франция и после в САЩ. Пише за тоталитаризма и за „баналността на злото“. Умира в Ню Йорк през 1975 г. на 69 години.", "Наблюдава процеса срещу Айхман и вижда в него не чудовище, а обикновен чиновник.", "Ученичка е на философа Мартин Хайдегер."],
  "Емилиян Станев": ["Български писател от Търново. Пише романа „Антихрист“ и разкази за природата и животните, като „Крадецът на праскови“. Страстен ловец. Умира през 1979 г. на 72 години.", "„Крадецът на праскови“ е филмиран.", "Обича да броди сам из горите."],
  "Димитър Димов": ["Български писател и ветеринарен лекар от Ловеч. Пише романите „Тютюн“ и „Осъдени души“. Професор по анатомия. Умира внезапно в Букурещ през 1966 г. на 56 години.", "„Осъдени души“ се развива в Испания по време на Гражданската война.", "„Тютюн“ е пренаписван по поръчка на властта."],
  "Вили Бранд": ["Германски политик от Любек, роден като Херберт Фрам. Бяга от нацистите в Норвегия, после е кмет на Западен Берлин и канцлер на ФРГ. Търси помирение с Източна Европа и получава Нобелова награда за мир през 1971 г. Умира през 1992 г. на 78 години.", "През 1970 г. във Варшава коленичи пред паметника на жертвите от гетото – жест, обиколил света.", "Подава оставка, след като се оказва, че негов сътрудник е шпионин на ГДР."],
  "Борис Христов": ["Български оперен певец бас от Пловдив. Пее на най-големите сцени в света и е прочут с ролята на Борис Годунов. Живее в Италия и умира в Рим през 1993 г. на 79 години. Погребан е в София.", "Пее в хора на „Александър Невски“, преди да стане световна звезда.", "Записва всички песни на Мусоргски."],
  "Валери Петров": ["Български поет, драматург и преводач от София. Пише сценария на „Рицар без броня“ и приказката „Бяла приказка“, превежда всички пиеси на Шекспир. Умира през 2014 г. на 94 години.", "Превежда сам цялото драматично творчество на Шекспир.", "По неговите текстове са песни, които се пеят и до днес."],
  "Блага Димитрова": ["Българска поетеса и писателка от Бяла Слатина. Пише стихове и романи, а след 1989 г. става вицепрезидент на България. Умира през 2003 г. на 81 години.", "През войната във Виетнам осиновява виетнамско момиче.", "Романът ѝ „Лавина“ е филмиран."],
  "Апостол Карамитев": ["Български актьор от Дупница. Играе в театъра и в киното и преподава актьорско майсторство на поколения актьори. Умира през 1973 г. на 50 години.", "Синът му Момчил Карамитев също е актьор."],
  "Георги Калоянчев": ["Български актьор от Бургас, „Калата“, любимец на няколко поколения. Играе комедийни и драматични роли в театъра и киното. Умира през 2012 г. на 87 години.", "Наричан е „кралят на комедията“."],
  "Гюнтер Грас": ["Германски писател от Данциг. През 1959 г. пише „Тенекиеният барабан“ – за момче, което отказва да расте. Получава Нобелова награда през 1999 г. Умира през 2015 г. на 87 години.", "На 17 години е бил войник в СС – признава го чак на 78.", "Освен писател е и скулптор и художник."],
  "Николай Гяуров": ["Български оперен певец бас от Велинград. Пее в „Ла Скала“, „Метрополитън“ и Виена и е смятан за един от най-великите басове. Умира в Модена през 2004 г. на 74 години.", "Женен е за италианската сопрано Мирела Френи."],
  "Михаел Енде": ["Германски писател от Гармиш. Пише „Момо“, „Безкрайната история“ и „Джим Копчето и Лукас машинистът“. Умира през 1995 г. на 65 години.", "„Безкрайната история“ е отпечатана с два цвята мастило – за двата свята.", "Не харесва филма по книгата си и съди продуцентите."],
  "Хелмут Кол": ["Германски политик от Лудвигсхафен. Канцлер 16 години – най-дълго след Бисмарк. През 1990 г. обединява Германия и подкрепя създаването на еврото. Умира през 2017 г. на 87 години.", "Наричат го „канцлерът на обединението“.", "Обича да води чужди гости на свинско шкембе в родния си Пфалц."],
  "Христо Явашев – Кристо": ["Български художник от Габрово, известен в света като Кристо. Заедно със съпругата си Жан-Клод опакова сгради и пейзажи – Райхстага в Берлин, Пон Ньоф в Париж. Умира в Ню Йорк през 2020 г. на 84 години.", "С Жан-Клод са родени в един и същи ден – 13 юни 1935 г.", "Плаща всичките си проекти сам, като продава скици."],
  "Невена Коканова": ["Българска актриса от Дупница, една от най-обичаните в киното. Играе в „Сладко и горчиво“, „Иконостасът“ и „Князът“. Умира през 2000 г. на 61 години.", "Играе в над 30 филма.", "Започва в киното без актьорско образование."],
  "Роми Шнайдер": ["Австрийско-германска актриса от Виена. Става звезда на 17 години като императрица Сиси, а после играе във Франция в много силни филми. След смъртта на сина си умира през 1982 г. на 43 години.", "Мрази ролята на Сиси, защото всички я свързват само с нея.", "Сгодена е за Ален Делон."],
  "Тодор Колев": ["Български актьор, шоумен и певец от Шумен. Играе в комедии като „Опасен чар“ и води популярни телевизионни предавания. Умира през 2013 г. на 74 години.", "Наричан е „Великия“.", "Пее и свои песни."],
  "Емил Димитров": ["Български певец и композитор от Пловдив, звезда на естрадата. Пише и пее „Моя страна, моя България“ и „Арлекино“. Умира през 2005 г. на 64 години.", "Песента „Моя страна, моя България“ е като втори химн.", "Плочите му се продават в милиони и в СССР."],
  "Гена Димитрова": ["Българска оперна певица сопрано от Бейково. Пее на най-големите сцени – „Ла Скала“, „Метрополитън“, Арена ди Верона – и е прочута като Турандот. Умира през 2005 г. на 64 години.", "Наричат я „гласът на века“.", "Турандот е нейната коронна роля по целия свят."],
  "Стефан Данаилов": ["Български актьор от София, любимец на публиката. Играе в над 100 филма, сред тях „На всеки километър“, и в италиански филми. По-късно е министър на културата. Умира през 2019 г. на 76 години.", "Ролята на Деянов в „На всеки километър“ го прави звезда.", "Снима се в италианския сериал „Октопод“."],
  "Георги Аспарухов – Гунди": ["Български футболист от София, легенда на „Левски“. Голмайстор с изящен стил, играе на три световни първенства. Загива при автомобилна катастрофа през 1971 г. на 28 години.", "На погребението му идват около 550 000 души.", "Отказва оферта от „Милан“, за да остане в „Левски“."],
  "Франц Бекенбауер": ["Германски футболист от Мюнхен, „Кайзера“. Капитан на Германия, световен шампион като играч през 1974 г. и като треньор през 1990 г. Измисля съвременната роля на либерото. Умира през 2024 г. на 78 години.", "Играе на полуфинал на световно първенство с изкълчено рамо, превързан.", "Като момче иска да играе за „Мюнхен 1860“, но след шамар от техен играч отива в „Байерн“."],
  "Фалко": ["Австрийски поп певец от Виена, роден като Йохан Хьолцел. Песента му „Rock Me Amadeus“ е първата немскоезична песен на първо място в САЩ. Загива при катастрофа в Доминиканската република през 1998 г. на 40 години.", "Има абсолютен слух още като дете.", "„Der Kommissar“ е световен хит."],
  "Петя Дубарова": ["Българска поетеса от Бургас. Пише свежи и искрени стихове още като ученичка и играе във филма „Ще дойда да те взема“. Слага край на живота си през 1979 г. на 17 години.", "Повечето ѝ стихове излизат след смъртта ѝ.", "Къщата ѝ в Бургас е музей."],
};
